  "仅供独立采集程序使用：同步绑定设备的资料和来源，不能浏览归档或管理中央。Mac 和 Android 完整客户端请选择本人客户端。": "Nur für eigenständige Erfassungsprogramme: synchronisiert Inhalte und Quellen des gebundenen Geräts, ohne Archivzugriff oder zentrale Verwaltung. Wählen Sie für die vollständige Mac- oder Android-App „Persönlicher Client“.",
