  "记录和索引为 JSON，图片保留原始格式。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "Aufzeichnungen und Indizes verwenden JSON; Bilder behalten ihr Originalformat. Dies sind private App-Verzeichnisse, kein geteiltes Album; bei der Deinstallation werden lokale Dateien gelöscht. Beim Entfernen einer Speicherkarte wird der Zugriff mit einem Hinweis beendet, ohne auf ein leeres Verzeichnis zu wechseln. Nach dem Wiederverbinden wird der Zugriff wiederhergestellt.",
