  "未授权或未配置模型，也可以保存资料。保存模型连接不会自动授权后台处理。": "Sie können Inhalte auch ohne Modelleinrichtung oder Autorisierung speichern. Das Speichern einer Modellverbindung autorisiert keine Hintergrundverarbeitung.",
  "授权后，仅新接收的资料触发自动处理；历史资料仍可在批准范围内作为参考。原文可能发送给所选模型服务并产生费用，具体费用取决于服务商。": "Nach der Genehmigung lösen nur neu empfangene Inhalte die automatische Verarbeitung aus. Ältere Inhalte können weiterhin im genehmigten Umfang als Referenz dienen. Originalinhalte können an die ausgewählten Modelldienste gesendet werden und Kosten beim Anbieter verursachen.",
  "模块使用固定模型或跟随模块默认。动态路由、成本调度与自动切换尚未启用。": "Module verwenden ein festes Modell oder folgen ihrer konfigurierten Standardeinstellung. Dynamisches Routing, Kostensteuerung und automatischer Fallback sind nicht aktiviert.",
