  "原授权模型已更改或不可用，请重新读取并核对模型。": "Ein zuvor genehmigtes Modell hat sich geändert oder ist nicht verfügbar. Laden Sie neu und überprüfen Sie die Modellauswahl.",
  "所有来源（包括之后新增的来源）": "Alle Quellen (einschließlich später hinzugefügter Quellen)",
