  "{0} 条来源资料": "{0} Quellaufzeichnungen",
  "最近进展": "Letzte Fortschritte",
  "打开相关资料与操作": "Zugehörige Aufzeichnungen und Aktionen öffnen",
  "每个分支按自己的输入范围推进；完成状态由实际执行记录确认。": "Jeder Zweig arbeitet seine eigenen Eingaben ab. Der Status spiegelt die tatsächlichen Ausführungsnachweise wider.",
  "这项工作直接推进，目前没有独立分支。": "Diese Arbeit läuft direkt, derzeit ohne eigenständige Zweige.",
