  "共 {0} 条来源资料。展开原文或查看 Agent 实际读取的内容。": "{0} Quellaufzeichnungen. Öffnen Sie ein Original oder prüfen Sie, was der Agent tatsächlich gelesen hat.",
  "查看 Agent 实际输入": "Tatsächliche Agent-Eingaben prüfen",
