  "生活回顾已保存": "Lebensrückblick gespeichert",
  "模型、记忆、文件处理与飞书设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开有未保存修改的配置页面时会先提醒。": "Modell-, Erinnerungs-, Dateiverarbeitungs- und Feishu-Einstellungen gelten beim Speichern. Andere Präferenzen werden über einen Bereitstellungsentwurf und Neustart geändert. Sie werden gewarnt, bevor Sie eine Konfigurationsseite mit ungespeicherten Änderungen verlassen.",
  "文件与语音": "Dateien und Sprache",
  "本地语音模型、转写与文件处理策略": "Lokale Sprachmodelle, Transkription und Dateiverarbeitungsrichtlinien",
  "未提供文字识别状态，无法判断是否已处理。": "Der OCR-Status wurde nicht bereitgestellt; der Verarbeitungsabschluss ist unbekannt.",
  "高级：遮挡 JSON": "Erweitert: JSON maskieren",
  "本机数据格式已退役，请清除应用存储后重新设置。": "Dieses lokale Datenformat wurde eingestellt. Löschen Sie den App-Speicher und richten Sie neu ein.",
  "整理所选记忆": "Ausgewählte Erinnerung konsolidieren",
  "从这条记忆开始整理": "Ab dieser Erinnerung konsolidieren",
  "从当前精选记忆开始，模型会按需检索你仍可读取的相关资料和原文；结果可能为空，也可能产生经独立审核的新记忆。": "Ausgehend von dieser ausgewählten Erinnerung kann das Modell zugehörige Aufzeichnungen und Originale abrufen, auf die Sie noch Zugriff haben. Es kann keine neue Erinnerung oder eine neue Erinnerung nach unabhängiger Prüfung erzeugen.",
  "仅选择此卡作为整合起点": "Nur diese Karte ist als Ausgangspunkt ausgewählt",
  "请先选择一条当前有效的精选记忆。": "Wählen Sie zuerst eine aktuell gültige hervorgehobene Erinnerung.",
  "整理方案": "Konsolidierungsrezept",
