  "请在目标设备打开日程建议并同步。结果不明时只核实已有事件，避免重复创建。": "Öffnen Sie „Terminvorschläge“ auf dem Zielgerät und synchronisieren Sie. Ist das Ergebnis unklar, verifizieren Sie nur vorhandene Termine, um Duplikate zu vermeiden.",
