  "保存后会交给该设备写入，备注中附加 #Mote 标记。不会邀请参与人，也不会修改或取消已有日程。": "Das ausgewählte Gerät fügt diesen Termin mit einer #Mote-Notiz hinzu. Es werden keine Einladungen versendet; vorhandene Termine bleiben unverändert.",
