  "自动回顾的时间安排属于部署配置，合并草稿并重启中央节点后生效。上方模型服务可以直接保存并应用。": "Zeitpläne für Rückblicke sind Bereitstellungseinstellungen. Führen Sie den Entwurf zusammen und starten Sie den zentralen Knoten neu, um sie anzuwenden. Die Modelleinstellungen oben gelten nach dem Speichern.",
