  "资料容量上限": "Speicherlimit",
  "正数保留周期会按采集时间自动清理旧记录。下载草稿不会删除资料；合并配置并重启前，请确认所选周期。": "Eine positive Aufbewahrungsfrist entfernt ältere Aufzeichnungen automatisch nach Erfassungszeit. Das Herunterladen des Entwurfs löscht nichts. Prüfen Sie die Frist, bevor Sie anwenden und neu starten.",
