  "自定义容量（MiB）": "Benutzerdefinierte Kapazität (MiB)",
  "文本检索始终可用。配置向量索引后，文本会提交给你选择的 Embedding 服务。": "Die Textsuche ist immer verfügbar. Bei konfiguriertem Vektorindex werden Texte an den von Ihnen gewählten Embedding-Dienst gesendet.",
  "Embedding 模型名称": "Name des Embedding-Modells",
  "留空使用文本检索；更换模型可能需要重建已有向量。": "Leer lassen für Textsuche. Ein Modellwechsel kann einen Neuaufbau der Vektoren erfordern.",
