  "暂无已注册来源。先在“来源”页面添加内容。": "Keine registrierten Quellen. Fügen Sie zuerst Inhalte auf der Seite „Quellen“ hinzu.",
  "保留了当前配置中未列出的来源 ID；可在高级选项检查。": "Nicht aufgeführte Quellen-IDs in Ihrer Konfiguration bleiben erhalten. Prüfen Sie sie in den erweiterten Optionen.",
  "高级来源 ID 与授权回调": "Erweiterte Quellen-IDs und OAuth-Callback",
