  "我的 K90 Pro Max / 工作电脑 / Chatbot": "Mein K90 Pro Max / Arbeitscomputer / Chatbot",
  "用于在下面的列表中识别和撤销连接。": "Zum Erkennen und Widerrufen dieser Verbindung in der Liste unten.",
  "当前是本机地址，手机扫码后会指向手机自己。跨设备连接请先填入可访问的 HTTPS 域名；本机地址可用于同一台电脑或明确配置了端口转发的开发环境。": "Dies ist eine Loopback-Adresse; ein Telefon würde sich mit sich selbst verbinden. Geben Sie für ein anderes Gerät eine erreichbare HTTPS-Domain ein. Loopback funktioniert auf demselben Computer oder mit ausdrücklich konfigurierter Portweiterleitung.",
  "连接类型": "Verbindungstyp",
  "连接设备": "Gerät verbinden",
  "连接 Chatbot": "Chatbot verbinden",
  "手机、Mac 与其他采集端": "Telefone, Macs und andere Erfassungsgeräte",
  "每份邀请仅能使用一次，10 分钟后失效。连接后得到独立采集凭据，不包含中央管理令牌。": "Jede Einladung kann nur einmal verwendet werden und läuft nach 10 Minuten ab. Die Kopplung stellt separate Erfassungs-Zugangsdaten ohne das zentrale Besitzer-Token aus.",
  "设备身份": "Geräteidentität",
  "邀请设备身份": "Geräteidentität der Einladung",
  "首次连接的新设备": "Neues Gerät",
  "从旧版手填令牌迁移或重新配对，请选择原设备以保留身份。成功配对后会替换该设备之前的采集凭据。": "Wählen Sie bei erneuter Kopplung das ursprüngliche Gerät, um seine Identität zu behalten. Eine erfolgreiche Kopplung ersetzt die bisherigen Zugangsdaten.",
  "正在生成…": "Wird erzeugt…",
