  "尚未启用 MCP。请在设置 → 来源与外部应用中开启 MCP，并配置独立读令牌后重启；写入还需明确启用并设置允许的信源。": "MCP ist deaktiviert. Aktivieren Sie es unter Einstellungen → Quellen und externe Apps, konfigurieren Sie ein separates Lesetoken und starten Sie neu. Schreibvorgänge erfordern zusätzlich eine ausdrückliche Aktivierung und erlaubte Quellen.",
