  "只读权限能检索归档中的个人资料，请只交给你信任的应用。": "Lesezugriff kann persönliche Archivdaten durchsuchen. Geben Sie ihn nur an vertrauenswürdige Apps weiter.",
  "只接受 OAuth 的客户端暂不能直接使用此 JSON。": "Clients, die nur OAuth unterstützen, können diese JSON noch nicht direkt verwenden.",
