  "在客户端打开「设置 → 连接」": "Öffnen Sie im Client „Einstellungen → Verbindung“",
  "Android 可以直接扫码；Mac 可以导入二维码图片。两端均支持粘贴邀请或导入 JSON 文件，确认节点地址后连接。": "Android kann direkt scannen; Mac kann ein QR-Bild importieren. Beide unterstützen das Einfügen einer Einladung oder das Importieren von JSON sowie das Bestätigen der Knoten-URL.",
  "有效期内，持有邀请的人可以领取该连接。请勿公开分享；关闭此页面不会取消邀请，需使用下面的取消按钮。": "Jeder mit einer gültigen Einladung kann sie einlösen. Teilen Sie sie nicht öffentlich. Das Schließen dieser Seite bricht sie nicht ab; verwenden Sie dazu „Abbrechen“ unten.",
