  "开关立即生效，已有文件保持原格式并可继续读取。记录正文和索引存储在 SQLite 中；客户端的本地存储可在各自开发者选项中设置。": "Gilt sofort. Vorhandene Dateien behalten ihr Format und bleiben lesbar. Aufzeichnungstexte und Indizes liegen in SQLite. Konfigurieren Sie den Client-Speicher in den Entwickleroptionen des jeweiligen Clients.",
