  "取消解密": "Entschlüsselung abbrechen",
  "关闭上方加密后，可将已有图片、原件和待上传分片逐项转换为明文。任务在后台运行，离开页面仍会继续；取消后保留已完成结果，可再次运行。连接凭据不参与转换。": "Deaktivieren Sie die Verschlüsselung oben, um vorhandene Bilder, Originale und ausstehende Upload-Teile im Hintergrund in Klartext umzuwandeln. Das Verlassen dieser Seite stoppt den Vorgang nicht. Ein Abbruch behält abgeschlossene Ergebnisse; führen Sie ihn erneut aus, um fortzufahren. Zugangsdaten sind ausgenommen.",
