  "采集在设备本机运行，同步按每台设备的偏好进行。": "Die Erfassung läuft lokal auf jedem Gerät; die Synchronisierung folgt den Geräteeinstellungen.",
  "扫码连接设备": "Scannen, um ein Gerät zu verbinden",
  "这里显示设备最近一次上报。较久未联系可能是定时、手动同步或网络变化，不能据此判断本机是否正在采集。": "Hier sehen Sie die letzte Meldung jedes Geräts. Eine lange Pause kann auf geplante oder manuelle Synchronisierung oder Netzwerkänderungen zurückgehen; sie sagt nicht aus, ob die lokale Erfassung läuft.",
  "从你的第一台设备开始": "Beginnen Sie mit Ihrem ersten Gerät",
  "生成一次性邀请，在手机或 Mac 的连接设置中确认。客户端也可以先在本机记录，稍后再连接。": "Erzeugen Sie eine Einmaleinladung und bestätigen Sie sie in den Verbindungseinstellungen Ihres Telefons oder Macs. Clients können vor dem Verbinden lokal erfassen.",
