  "诊断包包含运行状态、数量、耗时和最近事件，不包含笔记、截图、模型对话或访问令牌。客户端的采集、电量和本地队列诊断从各自 App 导出。": "Enthält Laufzeitzustand, Zähler, Zeiten und aktuelle Ereignisse; enthält keine Notizen, Screenshots, Modellunterhaltungen oder Token. Client-Diagnosen zu Erfassung, Akku und Warteschlange exportieren Sie in der jeweiligen App.",
