  "按文件类型选择处理方案。服务保存地址和密钥；方案保存独立参数；同一目录可对录音和图片采用不同方案。处理均由中央节点调度。": "Wählen Sie pro Dateityp einen Verarbeitungsplan. Dienste speichern URLs und Schlüssel; Pläne halten unabhängige Parameter. Ein Verzeichnis kann für Audio und Bilder unterschiedliche Pläne verwenden. Die Verarbeitung wird zentral geplant.",
