  "这是运行 Mote 中央节点的机器上的路径。节点会复制可读取的文件到归档。": "Ein Pfad auf dem Rechner, auf dem Ihr zentraler Knoten läuft. Lesbare Dateien werden in das Archiv kopiert.",
  "资料名称": "Materialname",
  "选填": "Optional",
  "例如：过去一年的随手记": "Zum Beispiel: die Kurznotizen des letzten Jahres",
  "告诉 Mote 如何理解这份资料": "Sagen Sie Mote, wie dieses Material zu interpretieren ist",
  "格式、作者与归属说明": "Hinweise zu Format, Autorenschaft und Zuordnung",
  "格式按所选 Source Pack 解析；说明用于资料背景和归属范围。": "Das ausgewählte Source Pack steuert die Formatanalyse. Hinweise liefern Hintergrund und Zuordnungsumfang des Materials.",
  "例如：这是我的日记，引用和 AI 回复属于原说话人。时间是北京时间；每篇日记独立保存。": "Zum Beispiel: Dies sind meine Tagebucheinträge. Zitate und KI-Antworten gehören ihren ursprünglichen Sprechern. Zeiten gelten in Pekinger Zeit; jeden Eintrag separat speichern.",
  "可一次说明格式、时间、作者，以及哪些内容属于你。模型按说明范围理解，第三方和 AI 引用保留原角色。": "Erklären Sie Format, Zeiten, Autoren und welche Inhalte Ihnen gehören an einer Stelle. Das Modell folgt dem Umfang Ihrer Hinweise und behält die ursprünglichen Rollen von Dritt- und KI-Zitaten bei.",
  "未填写也会保留原件，可检索已提取的正文；身份未知时，可保存有用的来源限定观察。": "Ohne Hinweise bleiben Originale erhalten und extrahierter Text durchsuchbar. Bei unbekannter Identität können nützliche Beobachtungen mit ihrem Quellumfang gespeichert werden.",
  "本次导入说明": "Hinweise für diesen Import",
  "说明按文字中的范围用于理解这次导入的资料，不会把第三方和 AI 引用整批变成你的表达。": "Hinweise gelten im genannten Umfang für das Material dieses Imports. Dritt- und KI-Zitate werden dabei nicht pauschal zu Ihren eigenen Aussagen.",
  "例如：这是我的聊天导出，张三是我。时间是北京时间；每段对话独立保存，保留消息的时间和附件关系。": "Zum Beispiel: Dies ist mein Chat-Export; Zhang San bin ich. Zeiten gelten in Pekinger Zeit. Jede Unterhaltung separat speichern, Nachrichtenzeiten und Anhangsverknüpfungen beibehalten.",
  "可以说明人物、时间、格式和需要保留的细节。含糊之处会出现在预览中。": "Erklären Sie Personen, Zeiten, Formate und zu erhaltende Details. Unklarheiten erscheinen in der Vorschau.",
  "先保存原件，解析完成后由你确认。": "Originale werden zuerst gespeichert. Bestätigen Sie nach der Analyse.",
