  "仅保留应用与播放状态；标题、作者、专辑等内容不采集。": "Nur App- und Wiedergabestatus werden gespeichert; Titel, Künstler und Alben werden nicht erfasst.",
  "这是应用公开的状态。媒体采集在客户端单独开启；通知使用权用于发现媒体会话，不保存通知正文或音频。音乐、有声书等内容类型由分析时结合证据判断。": "Dieser Status wird von der App veröffentlicht. Die Medienerfassung wird auf dem Client separat aktiviert. Der Benachrichtigungszugriff erkennt Mediensitzungen, ohne Benachrichtigungsinhalte oder Audio zu speichern. Inhaltstypen werden bei der Analyse anhand der Nachweise interpretiert.",
