  "在 Android 客户端开启媒体采集并授权，记录同步后会出现在这里。没有记录不代表没有播放。": "Aktivieren und autorisieren Sie die Medienerfassung auf Android. Aufzeichnungen erscheinen nach der Synchronisierung. Keine Aufzeichnungen bedeuten nicht, dass keine Wiedergabe stattfand.",
