  "按设备查看": "Nach Gerät",
  "媒体播放与前台应用使用分别计时，可能同时发生，不应相加。只累计独立媒体记录的播放采样区间；同一设备重叠区间合并，多台设备分别累计。应用或状态分组可能重叠。": "Medienwiedergabe und Vordergrundnutzung werden getrennt gemessen und können sich überschneiden; addieren Sie sie nicht. Nur unabhängige Wiedergabe-Sample-Intervalle zählen. Überschneidungen werden pro Gerät zusammengeführt; verschiedene Geräte werden getrennt summiert. App- und Zustandsgruppen können sich überschneiden.",
  "截图附带的媒体状态不重复计时。暂停、缓冲和观察空隙不补齐；播放进度或媒体总长度不等于收听时长，远程播放也不代表手机发声。": "Der an Screenshots angehängte Medienzustand wird nicht doppelt gezählt. Pausen, Pufferung und Beobachtungslücken werden nicht aufgefüllt. Wiedergabeposition und Mediendauer sind keine Hördauer; Remote-Wiedergabe bedeutet nicht, dass das Telefon Töne erzeugt hat.",
