  "个片段已处理过或没有可提取的正文，本次未重复处理。原始资料仍可查看。": "Segmente, die bereits verarbeitet wurden oder keinen extrahierbaren Text enthalten, wurden nicht erneut verarbeitet. Originale bleiben verfügbar.",
  "在设置中配置模型后，可从这里继续。": "Konfigurieren Sie ein Modell in den Einstellungen und fahren Sie dann hier fort.",
