  "周期已到，并且新增变化达到门槛时才运行。每分钟检查一次；保存后直接生效，进行中的窗口沿用启动时的设置。": "Läuft, wenn das Intervall fällig ist und neue Änderungen den Schwellenwert erreichen. Wird jede Minute geprüft. Gespeicherte Änderungen gelten sofort; laufende Durchläufe behalten ihre Ausgangseinstellungen.",
