  "记忆以文本保存，按“概览 → 内容与边界 → 原始证据”逐层展开，全文索引可从文本重建。自动生成的长期记忆需要你确认。高频上传建议保留较长周期和每轮上限。": "Erinnerungen werden als Text gespeichert und schrittweise erweitert: Überblick → Inhalt und Grenzen → Originalnachweise. Volltextindizes können neu aufgebaut werden. Automatisch erzeugte Langzeiterinnerungen erfordern Ihre Bestätigung. Verwenden Sie bei häufigen Uploads längere Intervalle und begrenzte Batches.",
