  "仅显示上报时可获取的字段。状态是当时的观察值；缺失不代表否或零。": "Nur zum Meldezeitpunkt verfügbare Felder werden angezeigt. Werte beschreiben Beobachtungen zu diesem Zeitpunkt; fehlende Werte bedeuten nicht falsch oder null.",
  "原始系统事件，不表示你已阅读通知或正在执行某项任务。熄屏不等于锁定；服务中断期间不补造事件。系统可能隐藏敏感通知。": "Rohe Systemereignisse belegen nicht, dass Sie eine Benachrichtigung gelesen oder eine Aufgabe ausgeführt haben. Bildschirm aus bedeutet nicht gesperrt. Lücken werden nicht rekonstruiert; das System kann sensible Benachrichtigungen ausblenden.",
  "文件访问时间也可能由同步程序或其他进程读取更新，不能据此断定你查看过文件。": "Dateizugriffszeiten können durch Synchronisierungstools oder andere Prozesse aktualisiert werden und beweisen nicht, dass Sie eine Datei angesehen haben.",
  "这是完整扫描发现来源消失的时间，无法确认实际删除时刻或原因，也可能是移动或重命名。": "Ein vollständiger Scan hat das Verschwinden zu diesem Zeitpunkt erkannt; daraus lässt sich weder Zeitpunkt noch Grund des Löschens ableiten. Die Datei wurde möglicherweise verschoben oder umbenannt.",
