  "目录使用中央节点本机 Codex 的登录账户。选择只填写模型 ID；实际请求仍使用本页配置的 API 协议与凭据。": "Verwendet das lokale Codex-Konto des zentralen Knotens. Die Auswahl füllt nur die Modell-ID; Anfragen nutzen weiterhin das hier konfigurierte Protokoll und die Anmeldedaten.",
  "根据当前地址和凭据自动加载；目录可见不代表支持工具调用，可使用下方测试连接验证。": "Wird anhand der aktuellen URL und Anmeldedaten geladen. Katalogsichtbarkeit garantiert keine Tool-Unterstützung; verwenden Sie unten „Verbindung testen“.",
