  "推理强度": "Reasoning-Aufwand",
  "选择“由模型决定”兼容更多模型；具体能力取决于所选模型。": "Die automatische Auswahl unterstützt mehr Modelle. Die Fähigkeiten hängen vom gewählten Modell ab.",
