  "单次模型请求超时须为 5–600 秒。": "Das Timeout einer einzelnen Modellanfrage muss 5–600 Sekunden betragen.",
  "Agent 总运行超时须为 5–3600 秒。": "Das Gesamtlaufzeit-Timeout des Agenten muss 5–3600 Sekunden betragen.",
  "Agent 总运行超时须为空，或为 5–3600 秒。": "Das Gesamtlaufzeit-Timeout des Agenten muss leer sein oder 5–3600 Sekunden betragen.",
  "5–600 秒；只限制一次 Provider API 请求，不包含后续工具循环。": "5–600 Sekunden; begrenzt nur eine einzelne Provider-API-Anfrage und schließt spätere Tool-Schleifen aus.",
  "可留空；限制从 Agent 开始到结束的整个运行周期，包含多次模型请求和工具调用。": "Optional; begrenzt den gesamten Agentenlauf von Anfang bis Ende, einschließlich mehrerer Modellanfragen und Tool-Aufrufe.",
  "5–3600 秒；限制一次 Agent 从开始到完成的整个运行周期。": "5–3600 Sekunden; begrenzt einen Agentenlauf von Anfang bis Ende.",
  "输出上限 / 超时": "Ausgabelimit / Timeouts",
  "Codex 管理输出；Agent 总运行超时 {0}": "Codex verwaltet die Ausgabe; Gesamtlaufzeit-Timeout des Agenten: {0}",
  "单次模型请求 / Agent 总运行超时": "Einzelne Modellanfrage / Gesamtlaufzeit-Timeout des Agenten",
  "不适用": "Nicht anwendbar",
  "高级设置 · 输出预算": "Erweitert · Ausgabebudget",
  "输出预算档位": "Ausgabebudget-Voreinstellung",
  " · 默认": " · Standard",
  "自定义 · 在右侧填写": "Benutzerdefiniert · Rechts eingeben",
  "常用默认 65,536；选择支持当前预算的模型。": "Standard ist 65.536. Wählen Sie ein Modell, das dieses Budget unterstützt.",
  "最大输出 token 数": "Maximale Ausgabetokens",
  "输出 token 上限": "Ausgabetoken-Limit",
  "1–128000。单次响应的上限，包含正文、HTML 及服务商计入的推理 token，不是固定生成长度、字数或图片大小。保存后生效。": "1–128000. Limit pro Antwort einschließlich Text, HTML und vom Anbieter gezählter Reasoning-Token. Es ist keine feste Antwortlänge, Wortzahl oder Bildgröße. Gilt nach dem Speichern.",
  "允许本机模型免密访问": "Lokale Modelle ohne Authentifizierung zulassen",
  "只适用于回环地址；容器中的“本机”指容器本身。": "Nur Loopback-Adressen. Innerhalb eines Containers bedeutet „lokal“ den Container selbst.",
  "自定义请求头操作": "Aktion für benutzerdefinierte Header",
  "自定义请求头 JSON": "Benutzerdefinierte Header (JSON)",
  "名称与值均为字符串；整体替换。已有值不会读取或回显。": "Namen und Werte müssen Zeichenketten sein. Ersetzt das gesamte Objekt; vorhandene Werte werden nie angezeigt.",
  "高级请求参数操作": "Aktion für erweiterte Parameter",
  "高级请求参数 JSON": "Erweiterte Parameter (JSON)",
  "按当前协议填写 JSON 对象，整体替换。消息、工具与其他运行必需字段由 Mote 管理；已有值不会回显。": "Geben Sie ein JSON-Objekt für das aktuelle Protokoll ein. Ersetzt das gesamte Objekt. Mote verwaltet Nachrichten, Tools und erforderliche Felder; vorhandene Werte werden ausgeblendet.",
  "允许在更改后的服务地址复用已保存的凭据": "Gespeicherte Anmeldedaten bei geänderter Dienst-URL zulassen",
  "这会把保留的 API key、请求头或高级参数发送到当前填写的地址。也可以改为填写新值或清除旧值。": "Sendet gespeicherte API-Schlüssel, Header oder erweiterte Parameter an die eingegebene URL. Alternativ können Sie neue Werte eingeben oder alte löschen.",
  "测试连接会由中央节点发送少量合成内容，最多等待 30 秒，可能产生少量费用；不会读取资料库。测试不会保存草稿。": "Der Test sendet eine kleine synthetische Anfrage vom zentralen Knoten, wartet bis zu 30 Sekunden und kann geringe Kosten verursachen. Er liest nicht das Archiv und speichert den Entwurf nicht.",
  "（{0} 秒）": "({0} Sekunden)",
  "；保存后才会应用草稿。": "; speichern Sie, um den Entwurf anzuwenden.",
