  "恢复部署配置": "Bereitstellungseinstellungen wiederherstellen",
  "删除本页保存的模型配置，立即重新使用中央节点的启动环境或部署配置。当前未保存的草稿也会清空；不会修改部署文件。": "Löscht die hier gespeicherten Modelleinstellungen und stellt sofort die Start- oder Bereitstellungseinstellungen wieder her. Ungespeicherte Entwürfe werden gelöscht. Bereitstellungsdateien bleiben unverändert.",
  "正在恢复…": "Wird wiederhergestellt…",
  "确认恢复部署配置": "Wiederherstellen der Bereitstellungseinstellungen bestätigen",
  "随手记已同步到你的中央节点。": "Kurznotiz mit Ihrem zentralen Knoten synchronisiert.",
