  "Mote 随手记": "Mote-Kurznotiz",
  "已保存到本机待同步队列，联网后会继续同步。": "In der lokalen Warteschlange gespeichert. Die Synchronisierung wird bei Verbindung fortgesetzt.",
  "移除这条本机待同步副本？若中央节点已收到但确认丢失，需要在下方历史记录中另行删除。": "Diese ausstehende lokale Kopie entfernen? Wenn der Knoten sie empfangen hat, aber die Bestätigung verloren ging, löschen Sie die archivierte Aufzeichnung separat unten.",
  "想到什么，就记下来。": "Schreiben Sie es auf, sobald es Ihnen einfällt.",
