  "保存并同步": "Speichern und synchronisieren",
  "草稿和待同步内容保存在此应用的本机存储中，清除应用数据会移除它们。打开随手记时自动续传；按中央节点地址分别保存。": "Entwürfe und ausstehende Notizen werden lokal pro URL des zentralen Knotens gespeichert. Das Löschen der App-Daten entfernt sie. Die Synchronisierung wird fortgesetzt, wenn Kurznotizen geöffnet wird.",
