  "诊断、日志与高级生效配置": "Diagnose, Protokolle und erweiterte aktive Einstellungen",
  "模型与记忆设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开设置页面或返回上级菜单时，未保存的输入会丢弃。": "Modell- und Erinnerungseinstellungen gelten nach dem Speichern. Andere Präferenzen nutzen einen Bereitstellungsentwurf und einen Neustart. Ungespeicherte Eingaben werden verworfen, wenn Sie die Einstellungen verlassen oder zum übergeordneten Menü zurückkehren.",
