  "此渠道暂时没有可用的签名发布版本。": "In diesem Kanal ist noch keine signierte Version verfügbar.",
  "更新检查未通过，现有程序和设置保持原样；稍后可重试。": "Update-Prüfung fehlgeschlagen. Bestehende Software und Einstellungen bleiben unverändert. Versuchen Sie es später erneut.",
  "发现 {0}，发布签名已验证。": "{0} gefunden; Release-Signatur verifiziert.",
  "已是最新版本，发布签名已验证。": "Auf dem neuesten Stand; Release-Signatur verifiziert.",
  "查看版本说明与安装包": "Versionshinweise und Downloads anzeigen",
  "上次检查：": "Zuletzt geprüft:",
  "在部署机的 Mote 目录执行。命令先校验下载并准备程序，再备份、切换和检查健康状态。新版启动失败时保留快照，使用回退命令恢复。": "Im Mote-Verzeichnis auf dem Bereitstellungshost ausführen. Der Befehl verifiziert und bereitet den Download vor, sichert dann, wechselt und prüft den Zustand. Wenn der Start fehlschlägt, verwenden Sie Rollback, um den zurückbehaltenen Snapshot wiederherzustellen.",
  "需要回退时": "Zum Zurücksetzen",
  "回退恢复升级前的数据快照；升级后的资料会另行保留。不要直接用旧程序打开已升级的数据。": "Rollback stellt den Snapshot vor dem Update wieder her und bewahrt neuere Daten separat auf. Öffnen Sie aktualisierte Daten nicht direkt mit einem älteren Programm.",
  "此节点未由命名部署环境管理。请先按部署文档建立对应环境，再使用更新命令；本页面不会直接重启当前服务。": "Dieser Knoten wird nicht von einer benannten Bereitstellungsumgebung verwaltet. Richten Sie zuerst eine entsprechende Umgebung gemäß der Bereitstellungsdokumentation ein, bevor Sie Update-Befehle verwenden. Diese Seite startet den Dienst nicht neu.",
