  "连接 Google Calendar": "Google Calendar verbinden",
  "由中央节点定时同步你选定的日历，只申请读取权限。取消连接会移除本机授权，历史资料仍保留。": "Der zentrale Knoten synchronisiert ausgewählte Kalender regelmäßig mit Lesezugriff. Beim Trennen wird die lokale Autorisierung entfernt, der Verlauf bleibt erhalten.",
  "请先在设置 → 来源与外部应用中准备 Google OAuth 客户端与回调地址，然后重启节点。": "Bereiten Sie zuerst den Google-OAuth-Client und die Callback-Adresse unter Einstellungen → Quellen und externe Apps vor und starten Sie dann den Knoten neu.",
