  "成功率与耗时仅统计已结束运行；失败运行的已上报消耗仍计入。Skill 指运行入口指定的主流程，每笔消耗只归属一次，不拆分动态调用的子 Skill。": "Erfolgsraten und Dauern umfassen nur beendete Ausführungen. Gemeldete Nutzung fehlgeschlagener Ausführungen zählt weiterhin. Skill bezeichnet den primären Einstiegs-Workflow; jede Nutzung wird einmal zugeordnet, dynamisch aufgerufene Subskills werden nicht aufgeteilt.",
  "当前日期和筛选条件下没有用量记录。功能启用前的历史对话无法补算。": "Keine Nutzungsaufzeichnungen für diese Daten und Filter. Ältere Unterhaltungen können nicht nachträglich gemessen werden.",
