  "填写服务商或你的套餐单价（每百万 tokens）。包括缓存折扣；订阅套餐无法据此推算实际扣费。价格在每次运行开始时固定。": "Geben Sie Anbieter- oder Tarifpreise pro Million Tokens ein, einschließlich Cache-Rabatten. Abonnementgebühren lassen sich aus diesen Schätzungen nicht ableiten. Preise werden zu Beginn jeder Ausführung festgelegt.",
