  "管理请求必须使用当前服务的 API 路径。": "Verwaltungsanfragen müssen den API-Pfad dieses Dienstes verwenden.",
  "入口等待服务响应超时（524）。请检查节点运行诊断；较慢的模型请求可能超过代理等待上限。": "Gateway-Zeitüberschreitung beim Warten auf den Dienst (524). Prüfen Sie die Knotendiagnose; langsame Modellanfragen können das Proxy-Zeitlimit überschreiten.",
  "上传超过中央节点或公网入口的大小限制（413）。可以分批上传，或将文件放到中央服务器后从目录导入。": "Der Upload überschreitet das Größenlimit des Knotens oder Gateways (413). Laden Sie in Batches hoch oder legen Sie Dateien auf dem Server ab und importieren Sie das Verzeichnis.",
  "入口暂时无法连接中央服务（502）。请检查中央进程和隧道的 origin 地址。": "Gateway kann den zentralen Dienst nicht erreichen (502). Prüfen Sie den zentralen Prozess und die Tunnel-Origin-URL.",
