  "这次观察没有发现可见的媒体会话；未公开媒体会话的应用可能无法被记录。": "Bei dieser Beobachtung wurden keine sichtbaren Mediensitzungen gefunden. Apps, die keine Mediensitzungen veröffentlichen, werden möglicherweise nicht aufgezeichnet.",
