  "应用通过系统公开的媒体状态；播放状态不代表你实际收听或专注。": "Von der App veröffentlichter Medienstatus belegt weder tatsächliches Hören noch Aufmerksamkeit.",
  "应用通过系统公开的媒体状态，不包含音频录制或语音转写。播放时长只累计已观察到的播放区间；暂停、未授权和采样空隙不会补齐，也不能据此确定你实际收听。": "Von der App veröffentlichter Medienstatus umfasst keine Audioaufnahme oder -transkription. Die Dauer zählt nur beobachtete Wiedergabeintervalle; Pausen, fehlende Berechtigung und Sampling-Lücken werden nicht aufgefüllt. Sie beweist kein tatsächliches Hören.",
