  "Codex Server 不暴露内部单次模型生成请求，此项不适用。": "Codex Server legt keine interne einzelne Modellgenerierungsanfrage offen; diese Einstellung gilt nicht.",
  "服务或地址已改变。请填写新凭据、清除旧凭据，或明确允许在新地址复用。": "Dienst oder URL geändert. Ersetzen oder löschen Sie Anmeldedaten oder erlauben Sie deren Wiederverwendung ausdrücklich.",
