  "本地队列仍绑定原节点，请恢复已确认的连接": "Lokale Warteschlange ist noch an den ursprünglichen Knoten gebunden. Stellen Sie die bestätigte Verbindung wieder her.",
  "中央 OCR 文字与本机结果冲突，已停止补写并保留中央原文字；本机副本保留待处理。": "Zentraler OCR-Text steht im Konflikt mit lokalen Ergebnissen. Weitere Schreibvorgänge gestoppt; zentraler Text und lokale Kopie bleiben zur Prüfung erhalten.",
  "中央已删除此记录，不会重新创建；本机副本保留待处理。": "Zentrale Aufzeichnung wurde gelöscht und wird nicht neu erstellt. Lokale Kopie bleibt zur Prüfung erhalten.",
  "上传失败，队列已保留": "Upload fehlgeschlagen; Warteschlange erhalten",
  "同步失败，本地记录已保留": "Synchronisierung fehlgeschlagen; lokale Aufzeichnungen erhalten",
  "质量范围 40–95，最长边范围 640–2560": "Qualität muss 40–95 sein; längste Kante 640–2560",
