  "远程中央节点必须使用 HTTPS；HTTP 只允许本机回环地址": "Entfernte Knoten erfordern HTTPS. HTTP ist auf Loopback-Adressen beschränkt.",
  "本地隐私模型地址不正确": "Ungültige URL des lokalen Datenschutzmodells",
  "本地隐私模型需要完整 HTTP 地址": "Das lokale Datenschutzmodell benötigt eine vollständige HTTP-URL",
  "隐私审查模型仅允许 localhost / 127.0.0.1 / ::1，且不能含账号或查询参数": "Datenschutz-Prüfmodelle sind auf localhost / 127.0.0.1 / ::1 beschränkt, ohne Anmeldedaten oder Abfrageparameter",
