  "自定义模型地址无效": "Ungültige benutzerdefinierte Modell-URL",
  "自定义模型需要完整 HTTPS 目录地址": "Benutzerdefinierte Modelle benötigen eine vollständige HTTPS-Verzeichnis-URL",
  "自定义模型地址必须为 HTTPS 且不能含账号、查询参数或锚点": "Die benutzerdefinierte Modell-URL muss HTTPS verwenden und darf keine Anmeldedaten, Abfragen oder Fragmente enthalten",
  "选择自定义来源后，请填写模型目录 URL": "Geben Sie eine Modellverzeichnis-URL für die benutzerdefinierte Quelle ein",
