  "审查图片最大边长": "Maximale Kante des Prüfbilds",
  "本地推理线程数": "Lokale Inferenz-Threads",
  "本地推理超时（毫秒）": "Lokales Inferenz-Timeout (Millisekunden)",
  "还有待上传记录，不能切换节点或令牌；请先完成上传或备份处理旧队列": "Ausstehende Aufzeichnungen verhindern den Wechsel von Knoten oder Token. Laden Sie sie hoch oder sichern und verarbeiten Sie zuerst die alte Warteschlange.",
  "还有待上传记录，不能切换中央节点；请先完成上传，或导出并移走旧队列后重启": "Ausstehende Aufzeichnungen verhindern den Knotenwechsel. Laden Sie sie hoch oder exportieren und verschieben Sie die alte Warteschlange vor dem Neustart.",
  "切换中央节点必须明确输入新节点令牌，不能复用已有令牌": "Der Knotenwechsel erfordert die explizite Eingabe eines neuen Tokens; vorhandene Token können nicht wiederverwendet werden",
  "远程部署至少需要 32 字符访问令牌": "Remote-Bereitstellung erfordert ein Zugriffstoken mit mindestens 32 Zeichen",
  "设备标识无效": "Ungültige Geräte-ID",
  "系统密钥存储不可用，无法解密令牌": "System-Schlüsselspeicher nicht verfügbar; Token kann nicht entschlüsselt werden",
  "无法读取配置：请检查系统密钥存储或备份后修复配置文件": "Konfiguration kann nicht gelesen werden. Prüfen Sie den System-Schlüsselspeicher oder sichern und reparieren Sie die Konfigurationsdatei.",
  "系统加密存储不可用，拒绝保存明文令牌": "Verschlüsselter Systemspeicher nicht verfügbar; Klartext-Token wird nicht gespeichert",
  "本地记录的节点绑定信息无效": "Ungültige Knotenbindung für lokale Aufzeichnungen",
  "本地待上传记录已绑定原节点或凭据，不能重新归属；请恢复原连接完成同步": "Ausstehende Aufzeichnungen sind an den ursprünglichen Knoten oder die ursprünglichen Anmeldedaten gebunden. Stellen Sie diese Verbindung zur Synchronisierung wieder her; eine Neuzuordnung ist blockiert.",
  "中央确认格式无效，原连接保持不变": "Ungültige zentrale Bestätigung; ursprüngliche Verbindung unverändert",
  "设备已在中央登记，或邀请已使用；请在中央选择此设备重新生成邀请": "Gerät bereits zentral registriert oder Einladung verwendet. Wählen Sie dieses Gerät zentral aus und generieren Sie eine weitere Einladung.",
  "邀请无效、已使用或已过期，请在中央重新生成": "Einladung ungültig, verwendet oder abgelaufen. Generieren Sie zentral eine neue.",
  "中央拒绝此凭据，可能已撤销；原连接未修改": "Der zentrale Knoten hat diese Anmeldedaten abgelehnt, möglicherweise widerrufen. Ursprüngliche Verbindung unverändert.",
  "此中央暂不支持连接邀请或连接检查，请升级中央，或使用手动连接": "Dieser Knoten unterstützt keine Einladungen oder Verbindungsprüfungen. Aktualisieren Sie ihn oder verbinden Sie sich manuell.",
  "连接请求过于频繁，请稍后再试": "Zu viele Verbindungsanfragen. Versuchen Sie es später erneut.",
  "中央暂时无法连接，请稍后再试": "Zentraler Knoten vorübergehend nicht erreichbar. Versuchen Sie es später erneut.",
  "连接失败或超时；请检查中央地址、HTTPS 证书和网络，不接受重定向": "Verbindung fehlgeschlagen oder Zeitüberschreitung. Prüfen Sie die Knoten-URL, das HTTPS-Zertifikat und das Netzwerk. Weiterleitungen werden abgelehnt.",
  "请先导入连接邀请，或保存访问令牌": "Importieren Sie zuerst eine Einladung oder speichern Sie ein Zugriffstoken",
  "请导入连接邀请文字": "Einladungstext importieren",
  "请先预览邀请并确认显示的中央地址": "Zeigen Sie zuerst die Einladung in der Vorschau an und bestätigen Sie die angezeigte Knoten-URL",
  "还有待上传截图、随手记或来源版本，不能更换节点或凭据；请先完成上传或备份处理旧队列": "Ausstehende Screenshots, Kurznotizen oder Quellversionen verhindern den Wechsel von Knoten oder Anmeldedaten. Laden Sie sie hoch oder sichern und verarbeiten Sie zuerst die alte Warteschlange.",
  "当前采集、上传或来源同步尚未结束，请稍后重试连接": "Erfassung, Upload oder Quellsynchronisierung läuft noch. Versuchen Sie es später erneut.",
  "本地推理进程返回无效结果；本次截图已跳过": "Lokale Inferenz hat ein ungültiges Ergebnis zurückgegeben; Screenshot übersprungen",
  "本地模型推理失败；已回收推理进程，下次采样重新加载": "Lokale Inferenz fehlgeschlagen. Prozess neu gestartet; das Modell wird beim nächsten Sample neu geladen.",
  "本地推理进程已退出；本次截图已跳过，下次采样自动恢复": "Lokale Inferenz beendet; Screenshot übersprungen. Sie wird beim nächsten Sample wiederhergestellt.",
  "本地推理客户端已关闭": "Lokaler Inferenz-Client geschlossen",
  "本地推理正在处理上一张截图；本次已跳过": "Lokale Inferenz verarbeitet den vorherigen Screenshot; dieser wurde übersprungen",
