  "无法启动本地推理进程；本次截图已跳过": "Lokaler Inferenzprozess kann nicht gestartet werden; Screenshot übersprungen",
  "本地推理超时；已终止独立进程，本次截图已跳过": "Lokale Inferenz Zeitüberschreitung; isolierter Prozess beendet und Screenshot übersprungen",
