  "处理结束": "Verarbeitung abgeschlossen",
  "{0}：解密 {1}，跳过 {2}，失败 {3}；失败文件保留": "{0}: {1} entschlüsselt, {2} übersprungen, {3} fehlgeschlagen; fehlgeschlagene Dateien erhalten",
  "legacy（日常原目录）": "Legacy (ursprüngliches Tagesverzeichnis)",
  "连接尚未检查": "Verbindung nicht geprüft",
  "此连接仅有采集权限。请在设置的“连接与设备”中展开“设备身份与管理员访问”，使用单独管理员令牌打开中央仓库": "Diese Verbindung hat nur Erfassungszugriff. Verwenden Sie unter Einstellungen → Verbindung und Geräte → Geräteidentität und Eigentümerzugriff ein separates Eigentümer-Token, um das zentrale Archiv zu öffnen.",
  "完整中央仓库需要管理员权限；采集专用凭据不能用于此登录": "Das vollständige Archiv erfordert Eigentümerzugriff. Erfassungs-Anmeldedaten können sich hier nicht anmelden.",
  "连接已改变，请重新打开中央仓库": "Verbindung geändert. Öffnen Sie das zentrale Archiv erneut.",
