  "正在下载更新": "Update wird heruntergeladen",
  "正在准备安装更新": "Update-Installation wird vorbereitet",
  "正在检查更新": "Updates werden gesucht",
  "正在准备采集": "Erfassung wird vorbereitet",
  "正在结束当前采集": "Aktuelle Erfassung wird abgeschlossen",
  "正在保存随手记": "Kurznotiz wird gespeichert",
  "系统未允许修改登录启动项，请在系统设置检查": "Das System hat Änderungen an Anmeldeobjekten verweigert. Prüfen Sie die Systemeinstellungen.",
  "设置提交需要恢复；已停止采集与上传并保留数据，请重新打开 Mote。": "Die Übernahme der Einstellungen erfordert eine Wiederherstellung. Erfassung und Uploads gestoppt; Daten erhalten. Öffnen Sie Mote erneut.",
  "登录项还原失败": "Anmeldeobjekt konnte nicht wiederhergestellt werden",
  "设置未完成；原持久配置和截图保留，运行状态无法安全还原。请重新打开 Mote 后重试": "Einstellungen unvollständig. Persistente Konfiguration und Screenshots erhalten, aber der Laufzeitzustand konnte nicht sicher wiederhergestellt werden. Öffnen Sie Mote erneut und versuchen Sie es erneut.",
  "已安全保存采集凭据；可测试连接。完整仓库需单独管理员登录。": "Erfassungs-Anmeldedaten sicher gespeichert. Testen Sie die Verbindung; das vollständige Archiv erfordert eine separate Eigentümeranmeldung.",
  "连接已保存，可测试权限与节点版本": "Verbindung gespeichert. Testen Sie Berechtigungen und Knotenversion.",
  "连接邀请文件超过大小限制": "Einladungsdatei überschreitet das Größenlimit",
  "邀请导入方式无效": "Ungültige Einladungsimportmethode",
  "二维码图片导入暂仅支持 macOS，请使用 JSON 或连接链接": "QR-Bildimport erfordert derzeit macOS. Verwenden Sie JSON oder einen Verbindungslink.",
  "选择中央连接二维码图片": "QR-Bild für zentrale Verbindung auswählen",
  "选择中央连接邀请 JSON": "JSON der zentralen Verbindungseinladung auswählen",
  "无法读取有效邀请，请检查 JSON/二维码格式、有效期和文件大小；原连接未变动": "Keine gültige Einladung lesbar. Prüfen Sie JSON-/QR-Format, Gültigkeit und Dateigröße. Ursprüngliche Verbindung unverändert.",
  "系统加密存储不可用，不能交换并保存凭据": "Verschlüsselter Systemspeicher nicht verfügbar; Anmeldedaten können nicht ausgetauscht und gespeichert werden",
  "中央凭据身份确认不一致，原连接未修改；请重新生成邀请": "Identitätskonflikt bei zentralen Anmeldedaten. Ursprüngliche Verbindung unverändert; generieren Sie eine weitere Einladung.",
  "采集连接成功；可上传记录与同步自身来源，完整仓库需单独管理员登录": "Erfassung verbunden; Aufzeichnungen und eigene Quellen können synchronisiert werden. Das vollständige Archiv erfordert eine separate Eigentümeranmeldung.",
  "正在验证已保存连接与权限…": "Gespeicherte Verbindung und Berechtigungen werden geprüft …",
  "采集连接正常 · 仅上传与自身来源同步": "Erfassungsverbindung gültig · Nur Uploads und eigene Quellen",
  "管理员连接正常 · 可访问完整中央仓库": "Eigentümerverbindung gültig · Zugriff auf vollständiges zentrales Archiv",
  "连接检查失败；已保存配置未改变": "Verbindungsprüfung fehlgeschlagen; gespeicherte Konfiguration unverändert",
