  "正在准备解密；采集与同步会暂时暂停": "Entschlüsselung wird vorbereitet; Erfassung und Synchronisierung pausieren kurz",
  "解密未完成，原文件保留": "Entschlüsselung unvollständig; Originale erhalten",
  "选择本机截图保存位置": "Lokalen Screenshot-Speicherort auswählen",
  "选择位置": "Speicherort wählen",
  "无法打开截图目录，请检查磁盘是否已连接": "Screenshot-Verzeichnis kann nicht geöffnet werden. Prüfen Sie, ob die Festplatte angeschlossen ist.",
  "命名环境请使用带 --profile 的启动命令；系统默认登录项不能保留环境参数": "Starten Sie benannte Umgebungen mit --profile. Standard-Anmeldeobjekte des Systems können Umgebungsargumente nicht beibehalten.",
  "请通过本机文件夹选择器选择截图位置，再保存设置": "Wählen Sie den Screenshot-Speicherort mit der lokalen Ordnerauswahl und speichern Sie dann",
  "请先保存截图位置，再单独保存节点连接；每次切换均会自动应用": "Speichern Sie zuerst den Screenshot-Speicherort, dann separat die Knotenverbindung. Jeder Wechsel wird automatisch angewendet.",
  "请先停止采集，再修改本地模型": "Stoppen Sie die Erfassung, bevor Sie das lokale Modell ändern",
  "导入千问语言模型和视觉投影 GGUF（校验 SHA-256）": "Qwen-Sprach- und Vision-Projektions-GGUF-Dateien importieren (SHA-256-geprüft)",
  "导出已脱敏待上传队列（包含个人资料）": "Geschwärzte ausstehende Warteschlange exportieren (enthält persönliche Daten)",
  "导入 Mote 电脑端队列备份": "Mote-Desktop-Warteschlangen-Backup importieren",
  "Mote 存储或配置需要恢复": "Mote-Speicher oder -Konfiguration erfordert Wiederherstellung",
  "未开启采集，现有数据已保留": "Erfassung nicht gestartet; vorhandene Daten erhalten",
  "无法读取配置或持久队列": "Konfiguration oder persistente Warteschlange kann nicht gelesen werden",
  "{0}\n如使用外接磁盘，请连接原磁盘后重试。应用不会创建空队列替代原目录。": "{0}\nSchließen Sie bei Verwendung einer externen Festplatte die ursprüngliche Festplatte an und versuchen Sie es erneut. Die App ersetzt das ursprüngliche Verzeichnis nicht durch eine leere Warteschlange.",
