  "本地视觉请求过大": "Lokale Vision-Anfrage zu groß",
  "本地 macOS 助手不可用": "Lokaler macOS-Helfer nicht verfügbar",
  "本地 macOS 助手执行失败，本次采集已跳过": "Lokaler macOS-Helfer fehlgeschlagen; Erfassung übersprungen",
