  "文件访问时间标记无法读取，请保留来源状态并修复": "Dateizugriffszeit-Markierung kann nicht gelesen werden. Behalten Sie den Quellstatus und reparieren Sie ihn.",
  "日历未授权或权限已撤销，请点击连接日历并检查系统设置": "Kalenderzugriff fehlt oder wurde widerrufen. Verbinden Sie Kalender und prüfen Sie die Systemeinstellungen.",
