  "日历列表格式无效": "Ungültige Kalenderliste",
  "所选日历已不可用；已暂停删除判断，请重新选择": "Ausgewählter Kalender nicht verfügbar. Löscherkennung pausiert; wählen Sie erneut.",
  "日历数据格式无效": "Ungültige Kalenderdaten",
