  "先连接你的中央节点，即可打开中央仓库。": "Verbinden Sie Ihren zentralen Knoten, um sein Archiv zu öffnen.",
  "此设备使用采集专用连接。填写管理员令牌后即可打开中央仓库。": "Dieses Gerät verwendet Nur-Erfassungs-Zugriff. Geben Sie ein Eigentümer-Token ein, um das Archiv zu öffnen.",
  "发现上次未完成的保存，点击保存可用原 ID 重试。": "Unvollständiger Speichervorgang gefunden. Speichern Sie erneut, um es mit der ursprünglichen ID zu versuchen.",
  "无法恢复随手记草稿，请重启应用。": "Kurznotizentwurf kann nicht wiederhergestellt werden. Starten Sie die App neu.",
  "草稿已保存到本机。": "Entwurf lokal gespeichert.",
  "草稿暂未保存，请保留正文并重试；如上次保存未完成，请重新打开窗口恢复原稿。": "Entwurf noch nicht gespeichert. Behalten Sie den Text und versuchen Sie es erneut. Wenn ein früherer Speichervorgang unvollständig ist, öffnen Sie das Fenster erneut, um ihn wiederherzustellen.",
  "已保存到本机。连接节点并确认后，再按你的策略同步。": "Lokal gespeichert. Verbinden und bestätigen Sie einen Knoten, dann synchronisieren Sie gemäß Ihrer Richtlinie.",
  "已保存到本机 · {0}上传。中央确认后清理待传记录。": "Lokal gespeichert · {0} Uploads. Ausstehende Aufzeichnungen werden nach zentraler Bestätigung gelöscht.",
  "保存未完成，请重试": "Speichern unvollständig. Erneut versuchen.",
  "数值诊断已导出。": "Numerische Diagnosen exportiert.",
  "暂无日志。诊断关闭时停止新增，历史仍可查看。": "Noch keine Protokolle. Deaktivierte Diagnosen stoppen neue Einträge; der Verlauf bleibt verfügbar.",
  "按文件原始顺序显示，可拖动选中或使用 ⌘/Ctrl+A、C 复制。": "Ursprüngliche Dateireihenfolge. Wählen Sie Text oder verwenden Sie ⌘/Strg+A und C zum Kopieren.",
  "刷新日志": "Protokolle aktualisieren",
  "日志读取失败，请点击查看本地日志重试。": "Protokolle können nicht gelesen werden. Öffnen Sie lokale Protokolle zum erneuten Versuch.",
  "支持包已导出；只含数值、配置开关和固定阶段事件。": "Support-Paket exportiert; enthält nur Metriken, Konfigurationsschalter und feste Phasenereignisse.",
  "编辑：": "Bearbeiten:",
  "新来源的保留与过滤规则": "Aufbewahrung und Filter für neue Quellen",
  "尚未连接本地来源。选择只包含你希望归档资料的目录。": "Keine lokalen Quellen verbunden. Wählen Sie ein Verzeichnis, das nur Material enthält, das Sie archivieren möchten.",
  "编码对话": "Coding-Unterhaltungen",
  "快照": "Snapshot",
  "所选系统日历": "Ausgewählte Systemkalender",
  " · 最近同步 ": " · Zuletzt synchronisiert ",
  "{0} · {1} 项 · 待传 {2} · 跳过 {3}{4}": "{0} · {1} Elemente · {2} ausstehend · {3} übersprungen{4}",
  "编辑规则": "Regeln bearbeiten",
  "暂停本机同步": "Lokale Synchronisierung pausieren",
  "恢复本机同步": "Lokale Synchronisierung fortsetzen",
  "已处理，下面显示各来源的当前同步状态。": "Fertig. Aktuelle Quellsynchronisierungsstatus werden unten angezeigt.",
  "操作未完成，请检查权限与配置后重试": "Vorgang unvollständig. Prüfen Sie Berechtigungen und Konfiguration und versuchen Sie es dann erneut.",
  "已授权，但系统中没有可选日历；请在系统日历中添加后重试": "Autorisiert, aber keine Kalender verfügbar. Fügen Sie einen im Systemkalender hinzu und versuchen Sie es erneut.",
  "本机默认目录中尚未发现受支持的 Agent 会话": "Keine unterstützten Agent-Sitzungen in lokalen Standardverzeichnissen gefunden",
  "请先选择要编辑的来源": "Wählen Sie zuerst eine Quelle zum Bearbeiten",
