  " · 发布 ": " · Veröffentlichung ",
  "当前 {0}{1}": "Aktuell {0}{1}",
  "更新检查未完成，请重试。": "Update-Prüfung unvollständig. Erneut versuchen.",
  "请先保存或还原设置修改，再安装更新。": "Speichern oder setzen Sie die Einstellungen zurück, bevor Sie das Update installieren.",
  "请先完成当前随手记输入，再安装更新。": "Beenden Sie die aktuelle Kurznotizeingabe vor der Installation.",
  "此设备采集与自身来源同步": "Erfassung und eigene Quellen dieses Geräts",
  "管理员": "Eigentümer",
  "权限：{0} · 中央 {1} · 环境 {2}": "Zugriff: {0} · Zentral {1} · Umgebung {2}",
  "已保存采集专用凭据；完整仓库需单独管理员登录。": "Erfassungs-Anmeldedaten gespeichert; vollständiges Archiv erfordert separate Eigentümeranmeldung.",
  "邀请到期：": "Einladung läuft ab:",
  "同一节点重新授权后，现有待传截图、随手记和来源版本将继续发往此地址。节点身份以此地址和 HTTPS 证书为准；请确认它仍由你控制。": "Nach der Neuautorisierung desselben Knotens werden ausstehende Screenshots, Kurznotizen und Quellversionen weiterhin an diese Adresse gesendet. Die Knotenidentität basiert auf dieser URL und dem HTTPS-Zertifikat; bestätigen Sie, dass Sie sie noch kontrollieren.",
  "更换节点时，本机必须没有待传截图、随手记或来源版本；设备 ID、隐私设置和本地模型将保留。": "Der Knotenwechsel erfordert keine ausstehenden Screenshots, Kurznotizen oder Quellversionen. Geräte-ID, Datenschutzeinstellungen und lokale Modelle bleiben erhalten.",
  "请先确认中央地址": "Bestätigen Sie zuerst die zentrale URL",
  "正在连接并验证新凭据，此过程无法取消；原配置在确认成功前保持不变。": "Verbindung wird hergestellt und Anmeldedaten werden geprüft; dies kann nicht abgebrochen werden. Ursprüngliche Konfiguration bleibt bis zum Erfolg bestehen.",
  "连接已安全保存；原设备 ID、隐私设置和本地模型保留。": "Verbindung sicher gespeichert. Geräte-ID, Datenschutzeinstellungen und lokale Modelle bleiben erhalten.",
  "应用 Bundle ID": "App-Bundle-ID",
  "应用采集级别": "App-Erfassungsstufe",
  "完整内容": "Vollständiger Inhalt",
  "不记录": "Ausschließen",
  "移除规则": "Regel entfernen",
  "应用规则": "App-Regeln",
  "自定义应用": "Benutzerdefinierte App",
  "应用规则需要填写 Bundle ID；不用的规则请移除": "Geben Sie eine Bundle-ID für jede App-Regel ein oder entfernen Sie nicht verwendete Regeln",
  "同一应用只能设置一条采集规则": "Pro App ist nur eine Erfassungsregel erlaubt",
  "实时": "Echtzeit",
  "定时": "Geplant",
