  "最长等待（分钟）": "Maximale Wartezeit (Minuten)",
  "上传间隔（分钟）": "Upload-Intervall (Minuten)",
  "记录保存后尽快发送。断网或失败时仍留在本机，稍后自动重试。": "Aufzeichnungen kurz nach dem Speichern senden. Offline oder fehlgeschlagene Aufzeichnungen bleiben lokal für automatische erneute Versuche.",
  "每 {0} 分钟检查并上传待传记录。休眠期间顺延，唤醒后继续。": "Ausstehende Aufzeichnungen alle {0} Minuten prüfen und hochladen. Verzögert im Ruhezustand; wird beim Aufwachen fortgesetzt.",
  "攒够 {0} 条，或最早记录等待 {1} 分钟后发送，以先达到的条件为准。每条记录单独确认接收。": "Bei {0} Aufzeichnungen senden oder wenn die älteste {1} Minuten wartet, je nachdem, was zuerst eintritt. Jede Aufzeichnung wird separat bestätigt.",
  "不自动上传记录或发送设备状态。点击概览的“立即上传”或来源页的“立即检查并上传”时发送；下次仍由你手动触发。": "Keine automatischen Uploads oder Geräteberichte. Verwenden Sie „Jetzt hochladen“ in der Übersicht oder „Jetzt prüfen und hochladen“ unter Quellen. Zukünftige Uploads erfordern ebenfalls manuelle Aktion.",
  "你填写的节点": "Ihr eingegebener Knoten",
  "本机有 {0} 条尚未绑定节点的待传记录，及可能尚未完成保存的随手记。确认后将归属 {1}，按上传策略发送。": "Es gibt {0} ungebundene ausstehende Aufzeichnungen und möglicherweise unvollständig gespeicherte Kurznotizen. Die Bestätigung ordnet sie {1} zu; Uploads folgen dann Ihrer Richtlinie.",
