  "{0} · {1}/{2} · 命中/成功 {3} · 跳过/失败 {4}": "{0} · {1}/{2} · Getroffen/erfolgreich {3} · Übersprungen/fehlgeschlagen {4}",
  "任务已取消，已完成的处理保留；可重新扫描或查看待决定区。": "Aufgabe abgebrochen; abgeschlossene Arbeit bleibt erhalten. Erneut scannen oder Quarantäne anzeigen.",
