  "同应用连续采样归为一段；切换应用或间隔超过 5 分钟分段。仅按本页日期与现存截图分组，起止范围不代表使用时长。": "Fortlaufende Stichproben in einer App bilden eine Sitzung; App-Wechsel oder Lücken über 5 Minuten beginnen eine neue. Gruppen nutzen vorhandene Screenshots dieses Datums. Zeitbereiche zeigen keine Nutzungsdauer.",
