  "保存在本机 · 待同步": "Lokal gespeichert · Synchronisierung ausstehend",
  "正在读取详情…": "Details werden geladen…",
  "本机记录已同步并清理，请切换到中央归档查看": "Lokale Aufzeichnung synchronisiert und bereinigt. Ansehen im zentralen Archiv.",
  "记录已读取，正在加载图片…": "Aufzeichnung geladen; Bild wird geladen…",
  "原始系统事件 · 不代表已阅读通知或实际执行某项任务。熄屏不等于锁定。": "Rohes Systemereignis beweist weder eine gelesene Benachrichtigung noch eine ausgeführte Aufgabe. Bildschirm aus bedeutet nicht gesperrt.",
  "此记录的已观察播放时长：{0} 秒（不含观测缺口）": "Beobachtete Wiedergabe in dieser Aufzeichnung: {0} Sekunden (ohne Beobachtungslücken)",
