  "此图片未识别到文字。": "In diesem Bild wurde kein Text erkannt.",
  "暂无识别文字。": "Noch kein erkannter Text.",
  "记录读取失败，请刷新重试": "Aufzeichnung kann nicht gelesen werden. Aktualisieren Sie und versuchen Sie es erneut.",
  "中央记录暂不可读取，请检查网络后重试": "Zentrale Aufzeichnung kann nicht gelesen werden. Prüfen Sie das Netzwerk und versuchen Sie es erneut.",
  "本机记录暂不可读取，请刷新重试；文件已保留": "Lokale Aufzeichnung kann nicht gelesen werden. Aktualisieren Sie und versuchen Sie es erneut; die Datei bleibt erhalten.",
  "采集状态": "Erfassungsstatus",
  "屏幕：{0}": "Bildschirm: {0}",
  "媒体：{0}": "Medien: {0}",
  "Mote · 采集状态": "Mote · Erfassungsstatus",
  "你已停止采集，已有记录保留，同步按所选策略运行": "Sie haben die Erfassung gestoppt. Aufzeichnungen bleiben erhalten; die Synchronisierung folgt der gewählten Richtlinie.",
  "同步与恢复": "Synchronisierung und Wiederherstellung",
  "手机负责采集，中央端负责归档。已上传的本机副本按保留时间清理。": "Das Telefon erfasst, der zentrale Knoten archiviert. Hochgeladene lokale Kopien werden nach Ablauf ihrer Aufbewahrungsfrist entfernt.",
  "正在读取本机同步状态…": "Lokaler Synchronisierungsstatus wird geladen…",
  "查看待上传队列": "Ausstehende Warteschlange anzeigen",
  "立即同步待发记录": "Ausstehende Aufzeichnungen jetzt synchronisieren",
  "从未确认的记录继续发送；上传中断只重发未确认记录。同一条记录重试不会生成重复副本。仍遵守 Wi-Fi 设置。": "Setzt bei nicht bestätigten Aufzeichnungen fort. Unterbrochene Uploads senden nur diese Aufzeichnungen erneut, ohne Duplikate zu erzeugen. WLAN-Einstellungen gelten weiterhin.",
  "检查两端记录状态": "Aufzeichnungen auf beiden Seiten prüfen",
  "只检查手机仍保留的采集记录在中央端是否可见；不会把“中央存在”直接当作上传确认，也不会删除或恢复记录。": "Prüft, ob auf dem Telefon noch aufbewahrte Aufzeichnungen zentral sichtbar sind. Zentrales Vorhandensein gilt nicht als Upload-Bestätigung; nichts wird gelöscht oder wiederhergestellt.",
  "全量补传 · 本机保留的记录": "Alle lokal aufbewahrten Aufzeichnungen erneut senden",
  "重新上传本机保留的数据？": "Lokal aufbewahrte Daten erneut hochladen?",
  "会重发本机仍保留的截图、OCR 原始事件、通知、设备事件、笔记及已启用来源的保留版本。中央端核验相同 ID 去重，继续补齐缺失数据。\n\n已从手机清理的数据无法补传。中央已删除或内容冲突的记录不会覆盖或恢复，暂停的来源不会启用。此操作可能产生较多流量，仍遵守网络设置。": "Sendet aufbewahrte Screenshots, ursprüngliche OCR-Ereignisse, Benachrichtigungen, Geräteereignisse, Notizen und aufbewahrte Revisionen aktivierter Quellen erneut. Zentrale ID-Prüfungen deduplizieren und schließen Lücken.\n\nBereits vom Telefon bereinigte Daten können nicht erneut gesendet werden. Zentral gelöschte oder in Konflikt stehende Aufzeichnungen werden nicht überschrieben oder wiederhergestellt; pausierte Quellen bleiben pausiert. Dies kann erheblichen Datenverkehr verursachen; Netzwerkeinstellungen gelten weiterhin.",
  "开始补传": "Erneutes Senden starten",
  "尚未执行检查或全量补传": "Noch keine Prüfung oder vollständige erneute Übertragung durchgeführt",
  "停止本次检查 / 准备补传": "Diese Prüfung / Vorbereitung der erneuten Übertragung stoppen",
  "已请求停止检查；已进入待发队列的记录按同步策略保留": "Stopp angefordert. Bereits eingereihte Aufzeichnungen bleiben gemäß Synchronisierungsrichtlinie bestehen.",
  "查看记录与冲突": "Aufzeichnungen und Konflikte anzeigen",
  "查看来源同步状态": "Synchronisierungsstatus der Quellen anzeigen",
  "需要处理时：\n• 网络或服务暂不可用：自动模式退避重试，手动模式再次点同步。\n• 授权失效：重新连接同一节点后同步。\n• 同 ID 内容冲突 / 中央已删除：保留本机副本，跳过该条继续其他记录，不自动覆盖。\n• 等待 OCR：图片已归档不代表识别完成，识别结果会另行确认。\n\n中央端显示的是上次联系时的状态，不是手机实时状态。": "Wenn Handlungsbedarf besteht:\n• Netzwerk/Dienst nicht verfügbar: Der Automatikmodus wiederholt mit Backoff; im manuellen Modus erneut auf „Synchronisieren“ tippen.\n• Berechtigung abgelaufen: Denselben Knoten neu verbinden, dann synchronisieren.\n• ID-Konflikt / zentrale Löschung: Lokale Kopie behalten und mit den übrigen Aufzeichnungen fortfahren, ohne zu überschreiben.\n• Warten auf OCR: Archivierte Bilder belegen nicht die abgeschlossene Erkennung; Ergebnisse werden separat bestätigt.\n\nDer zentrale Status zeigt den Stand des letzten Kontakts, nicht den aktuellen Telefonstatus.",
  "请先配置连接": "Zuerst eine Verbindung konfigurieren",
  "正在读取存储状态": "Speicherstatus wird gelesen",
  "{0}\n本机保留 {1} 条 · 待发 {2} 条\n需处理 {3} 条 · 等待 OCR {4} 张\n来源待发 {5} 个版本 / {6} 项设置\n\n{7}\n最后收到上传确认：{8}": "{0}\nLokal aufbewahrt {1} · Ausstehend {2}\nHandlungsbedarf {3} · Warten auf OCR {4}\nQuellen ausstehend {5} Revisionen / {6} Einstellungen\n\n{7}\nLetzte Upload-Bestätigung: {8}",
  "请检查存储": "Speicher prüfen",
