  "无法持久保存设置，请检查存储空间": "Einstellungen können nicht dauerhaft gespeichert werden. Freien Speicher prüfen.",
  "已保存设置发生变化，页面已更新；请检查后重新保存": "Gespeicherte Einstellungen wurden geändert; Seite aktualisiert. Bitte prüfen und erneut speichern.",
  "设置保存与恢复均未持久完成，采集已停止；请检查存储空间并重试": "Weder Speichern noch Wiederherstellen konnte die Einstellungen dauerhaft sichern. Erfassung gestoppt; Speicher prüfen und erneut versuchen.",
  "连接设置未能持久恢复，采集已停止；原连接恢复资料仍保留": "Verbindungswiederherstellung konnte nicht dauerhaft gespeichert werden. Erfassung gestoppt; ursprüngliche Wiederherstellungsdaten bleiben erhalten.",
  "待同步资料属于原节点，请先同步到原节点；清空连接不会解除资料绑定": "Ausstehende Daten gehören zum ursprünglichen Knoten. Zuerst dorthin synchronisieren; das Löschen der Verbindung löst die Bindung nicht.",
