  "原存储包含无法迁移的条目": "Der ursprüngliche Speicher enthält Einträge, die nicht migriert werden können",
  "复制校验失败，原数据已保留": "Kopierprüfung fehlgeschlagen; Originaldaten bleiben erhalten",
  "正在验证目标记录与图片": "Zielaufzeichnungen und -bilder werden geprüft",
  "存储迁移状态不一致，请保留应用数据": "Inkonsistenter Migrationsstatus. App-Daten aufbewahren.",
  "无法清理旧存储副本": "Alte Speicherkopie kann nicht bereinigt werden",
  "旧目录包含未知子目录，副本已保留": "Altes Verzeichnis enthält unbekannte Unterverzeichnisse; Kopie bleibt erhalten",
  "旧存储副本清理未完成": "Bereinigung des alten Speichers unvollständig",
  "当前连接没有查看此记录的权限，请检查连接凭据": "Die aktuelle Verbindung hat keine Berechtigung für diese Aufzeichnung. Zugangsdaten prüfen.",
  "此记录已不存在，或中央节点版本尚不支持浏览": "Aufzeichnung nicht mehr vorhanden oder Knotenversion unterstützt kein Durchsuchen",
