  " · 等待充电": " · Warten auf Stromversorgung",
  "OCR 待处理{0}": "OCR ausstehend{0}",
  "OCR 状态未知（历史记录）": "OCR unbekannt (ältere Aufzeichnung)",
  "连接或同步策略已变化，本次操作已停止；请重新发起": "Verbindung oder Synchronisierungsrichtlinie geändert. Vorgang gestoppt; bitte neu starten.",
  "正在准备全量补传…": "Vollständiges erneutes Senden wird vorbereitet…",
  "已安排补传 {0} 条本机采集记录及 {1} 个保留来源版本；实际上传进度见下方同步状态。冲突和中央已删除记录保持隔离。": "{0} lokale Erfassungen und {1} aufbewahrte Quellrevisionen zum erneuten Senden eingereiht. Fortschritt siehe Synchronisierungsstatus unten. Konflikte und zentral gelöschte Aufzeichnungen bleiben isoliert.",
  "检查完成：中央可见 {0} 条，不可见 {1} 条。检查范围为手机仍保留的采集记录；不可见可能是缺失、删除或无权限，不会自动恢复。来源快照由全量补传时核验。": "Prüfung abgeschlossen: {0} zentral sichtbar, {1} nicht sichtbar. Umfasst auf dem Telefon noch aufbewahrte Erfassungen. Nicht sichtbar kann fehlend, gelöscht oder nicht berechtigt bedeuten; nichts wird automatisch wiederhergestellt. Die vollständige erneute Übertragung prüft Quell-Snapshots.",
  "检查失败：连接授权失效，请重新连接同一节点后重试": "Prüfung fehlgeschlagen: Berechtigung abgelaufen. Denselben Knoten neu verbinden und erneut versuchen.",
  "中央节点尚不支持两端检查，请升级中央端代码；未修改本机状态": "Der zentrale Knoten unterstützt keine beidseitigen Prüfungen. Knoten aktualisieren; lokaler Status unverändert.",
  "检查响应未确认": "Prüfantwort nicht bestätigt",
  "检查响应缺失": "Prüfantwort fehlt",
  "已检查 {0} 条 · 中央可见 {1} · 不可见 {2}": "{0} Aufzeichnungen geprüft · Sichtbar {1} · Nicht sichtbar {2}",
  "操作未完成，已完成的步骤保留；请检查网络或存储。本次手动操作可再次点击继续，未删除任何副本。": "Vorgang unvollständig; abgeschlossene Schritte bleiben erhalten. Netzwerk oder Speicher prüfen und erneut tippen, um fortzufahren. Es wurden keine Kopien gelöscht.",
  "操作已请求；重复点击会合并，等待网络条件或当前操作完成": "Vorgang angefordert; wiederholte Taps werden zusammengeführt. Warten auf Netzwerkbedingungen oder laufende Arbeit.",
  "图片保存位置": "Bildspeicherort",
  "本机保存待同步、待 OCR 与保留期内的记录和图片。上传后仍可回看，到期才清理。": "Speichert lokal ausstehende Sync-/OCR-Aufzeichnungen und Bilder innerhalb der Aufbewahrungsfrist. Hochgeladene Aufzeichnungen bleiben bis zum Ablauf durchsuchbar.",
  "选择内部应用空间，或系统提供的本机／存储卡应用空间。迁移会自动暂停处理、复制并验证已有记录，然后继续原来的采集与同步。草稿、设置及来源缓存保留在内部空间。": "Internen App-Speicher oder systemseitigen lokalen/SD-Karten-App-Speicher wählen. Die Migration pausiert die Verarbeitung, kopiert und prüft Aufzeichnungen und setzt dann Erfassung und Synchronisierung fort. Entwürfe, Einstellungen und Quell-Cache bleiben intern.",
  "默认明文保存：记录和索引为 JSON，图片保留原始格式。开发者选项可开启本地内容加密，也可批量解密旧文件。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "Standardmäßig Klartext: Aufzeichnungen und Indizes als JSON, Bilder im Originalformat. In den Entwickleroptionen kann lokale Inhaltsverschlüsselung aktiviert oder alte Dateien stapelweise entschlüsselt werden. Dies sind app-private Verzeichnisse, kein geteiltes Album; die Deinstallation löscht lokale Dateien. Beim Entfernen der Karte wird der Zugriff mit Hinweis beendet, ohne zu einem leeren Verzeichnis zu wechseln; nach erneutem Verbinden kann es fortgesetzt werden.",
  "正在读取存储位置…": "Speicherorte werden geladen…",
  "当前保存位置\n{0}": "Aktueller Speicherort\n{0}",
  "位置不可用：{0}\n已保留原位置，请重新连接原介质后重试。": "Ort nicht verfügbar: {0}\nUrsprünglicher Ort beibehalten. Originalmedium erneut verbinden und erneut versuchen.",
  "（当前）": "(aktuell)",
  "{0}{1}\n可用 {2}\n{3}": "{0}{1}\nVerfügbar {2}\n{3}",
  "无法读取系统存储位置：{0}": "System-Speicherorte können nicht gelesen werden: {0}",
  "刷新存储状态": "Speicherstatus aktualisieren",
  "迁移本机保存位置": "Lokalen Speicherort migrieren",
  "迁移到{0}：\n{1}\n\n已有图片、待 OCR 结果和队列记录会一起迁移。验证成功后切换位置并清理旧副本。中央归档位置保持不变。": "Nach {0} migrieren:\n{1}\n\nBilder, ausstehende OCR-Ergebnisse und Warteschlangeneinträge werden zusammen migriert. Nach erfolgreicher Prüfung wird der Ort gewechselt und die alte Kopie bereinigt. Der zentrale Archivort bleibt unverändert.",
  "迁移并应用": "Migrieren und anwenden",
  "正在迁移并验证记录，请保持存储介质连接…": "Aufzeichnungen werden migriert und geprüft. Speichermedium verbunden lassen…",
  "保存位置已生效": "Speicherort übernommen",
  "迁移未完成": "Migration unvollständig",
  "请检查存储位置后重试，保留应用数据。": "Speicherort prüfen und erneut versuchen. App-Daten aufbewahren.",
  "连接与同步": "Verbindung und Synchronisierung",
