  "诊断与支持": "Diagnose und Support",
  "模型高级设置": "Erweiterte Modelleinstellungen",
  "正在读取本机设置…": "Lokale Einstellungen werden geladen…",
  "设置无法读取，原数据保留。请退出后检查存储或重试。": "Einstellungen können nicht gelesen werden; Originaldaten bleiben erhalten. Beenden, Speicher prüfen und erneut versuchen.",
  "保存设置": "Einstellungen speichern",
  "让经历留有线索": "Erlebnisse hinterlassen Spuren",
  "此刻的 Mote": "Mote jetzt",
  "未连接节点也能采集；随时可以暂停。": "Erfassung funktioniert ohne Knoten und lässt sich jederzeit pausieren.",
  "同步状态": "Synchronisierungsstatus",
  "正在读取同步状态…": "Synchronisierungsstatus wird geladen…",
