  "{0}\n\n本机已有尚未绑定的截图、笔记或来源资料。确认后会绑定到这个档案地址，并按你的同步策略发送。请核对这是你自己的节点。": "{0}\n\nAuf diesem Gerät sind noch nicht gebundene Screenshots, Notizen oder Quelldaten vorhanden. Nach Bestätigung werden sie an diese Archivadresse gebunden und gemäß Ihrer Synchronisierungsrichtlinie gesendet. Bitte prüfen Sie, dass dies Ihr eigener Knoten ist.",
