  "尚未连接中央节点，请导入邀请或填写下方设置。": "Noch kein zentraler Knoten verbunden. Einladung importieren oder die Einstellungen unten ausfüllen.",
  "已保存节点：{0}": "Gespeicherter Knoten: {0}",
  "媒体播放状态授权": "Autorisierung des Medienwiedergabestatus",
  "Android 通过通知使用权开放通知与媒体会话。开启通知采集后，Mote 会保存应用公开的标题、正文、持续状态以及更新和移除事件，并按同步策略上传。设备事件单独记录亮屏、熄屏和锁定状态。各来源需单独开启并点击开始；应用的“不记录”和“仅活动”规则仍适用。系统可能隐藏敏感通知；Mote 不回复通知、不控制播放。": "Android gibt Benachrichtigungen und Mediensitzungen über den Benachrichtigungszugriff frei. Bei aktivierter Benachrichtigungserfassung speichert Mote öffentliche Titel, Texte, Dauerstatus sowie Aktualisierungs- und Entfernungsereignisse und lädt sie nach Richtlinie hoch. Geräteereignisse zeichnen separat Bildschirm an/aus und Sperrstatus auf. Jede Quelle muss einzeln aktiviert und „Start“ getippt werden; App-Regeln „Nicht aufzeichnen“ und „Nur Aktivität“ gelten weiterhin. Das System kann sensible Benachrichtigungen verbergen; Mote antwortet nicht auf Benachrichtigungen und steuert keine Wiedergabe.",
  "此系统入口不同，请在应用详情或系统搜索中查找": "Dieses System hat einen anderen Einstieg; in App-Details oder Systemsuche suchen.",
