  "随手记已保存在队列；同步调度暂不可用，再次保存会重试同一条记录": "Notiz in der Warteschlange gespeichert; Synchronisierungsplanung derzeit nicht verfügbar. Erneutes Speichern versucht dieselbe Aufzeichnung erneut.",
