  "固定遮罩示意图。在图上拖动添加矩形，点按矩形选中。也可用下方按钮添加和调整。": "Schematische Darstellung der festen Maske. Ziehen Sie, um Rechtecke hinzuzufügen; tippen Sie eines zur Auswahl an. Nutzen Sie die Schaltflächen unten, um Bereiche hinzuzufügen oder anzupassen.",
  "这些统计始终在本机保存，与开发者诊断开关独立。记录固定结果与数字，不记录画面、文字、应用名、邀请或令牌。": "Diese Statistiken werden immer lokal gespeichert, unabhängig vom Diagnoseschalter. Sie enthalten feste Ergebnisse und Zahlen, keine Bilder, Texte, App-Namen, Einladungen oder Token.",
