  "上传待重试结果 {0} · 来源版本已确认 {1} / 失败 {2}\n设备心跳失败 {3}\n": "Upload-Wiederholungsergebnisse {0} · Quellenversionen bestätigt {1} / Fehlgeschlagen {2}\nHeartbeat-Fehler {3}\n",
  "已确认上传 JSON 字节 {0}（不含 TLS/HTTP 开销）\n": "Bestätigte Upload-JSON-Bytes {0} (ohne TLS/HTTP-Overhead)\n",
  "\n记录明细抽样\n采集区保留：{0} 条，截图 {1} / 活动 {2} / 媒体 {3} / 系统事件 {4} / 笔记 {5} / 无法读取 {6} / 未检查 {7}（分类最多读取100条）\n": "\nAufzeichnungsdetails (Stichprobe)\nBehaltene Erfassungen: {0}; Screenshots {1} / Aktivität {2} / Medien {3} / Systemereignisse {4} / Notizen {5} / Nicht lesbar {6} / Nicht geprüft {7} (Klassifizierung liest höchstens 100 Aufzeichnungen)\n",
  "\n资料在哪里\n队列存储：{0} / 上限 {1} MiB\n{2}\n": "\nSpeicherorte der Daten\nWarteschlangenspeicher: {0} / Limit {1} MiB\n{2}\n",
  "待 OCR 文字预留：{0}（计入存储上限，完成识别后按实际大小计）\n": "Reservierter OCR-Text: {0} (zählt zum Speicherlimit; nach der Erkennung gilt die tatsächliche Größe)\n",
  "来源待确认版本：{0} · 本机来源缓存 {1}\n{2}\n": "Quellenversionen mit ausstehender Bestätigung: {0} · Lokaler Quellen-Cache {1}\n{2}\n",
