  "应用私有文件合计：{0}\n设备此分区可用：{1}\n": "Private App-Dateien gesamt: {0}\nFreier Speicher dieser Partition: {1}\n",
  "目录大小为最近测量值，最多缓存 30 秒；可点击上方刷新重新测量。\n": "Verzeichnisgrößen sind zuletzt gemessene Werte und werden bis zu 30 Sekunden zwischengespeichert. Aktualisieren Sie oben, um erneut zu messen.\n",
  "\n生效设置\n实际配置：每 {0} 秒，JPEG {1}，最长边 {2}px\n": "\nAktive Einstellungen\nTatsächliche Konfiguration: alle {0} Sekunden, JPEG {1}, längste Kante {2}px\n",
  "开启": "Ein",
  "仅非计费 Wi-Fi：{0} · 仅充电采集：{1} · 低于 {2}% 暂停（0 关闭）\n": "Nur unbegrenztes WLAN: {0} · Erfassung nur beim Laden: {1} · Pause unter {2} % (0 deaktiviert)\n",
  "开启，充电后补做历史图片": "Ein; ältere Bilder werden beim Laden nachverarbeitet",
