  "本机过滤：{0} · {1} 线程 · {2}ms 超时\n": "Lokale Filterung: {0} · {1} Threads · {2}ms Zeitlimit\n",
  "上传新记录的实际状态": "Beobachteten Status mit neuen Aufzeichnungen hochladen",
  "新记录不附带": "Bei neuen Aufzeichnungen weglassen",
  "设备元数据：{0} · 应用规则 {1} 项\n": "Gerätemetadaten: {0} · {1} App-Regeln\n",
  "\n统计口径与限制\n已保存表示本机入队成功；已上传表示节点已确认收到。待 OCR 的图片在确认上传后仍会保留，补做结果也同步成功后才清理。被过滤的画面不会入队。暂停是原因变更次数，不等于丢弃截图次数；请求可能因系统/进程中断没有后续结果。统计与队列分开持久化，进程在两次写入之间终止时累计数可能少记；当前队列数量包含待识别和同步失败保留的图片。\n": "\nDefinitionen und Grenzen\n„Gespeichert“ bedeutet lokal eingereiht; „hochgeladen“ bedeutet vom Knoten bestätigt. Bilder mit ausstehender OCR bleiben nach dem Upload erhalten, bis auch die OCR-Ergebnisse synchronisiert sind. Gefilterte Frames werden nicht eingereiht. Pausenzähler erfassen Grundwechsel, nicht verworfene Screenshots. Unterbrochene Anfragen können ohne Ergebnis bleiben. Statistiken und Warteschlangen werden getrennt gespeichert; ein Abbruch zwischen zwei Schreibvorgängen kann Summen zu niedrig ausweisen. Warteschlangenzahlen enthalten Bilder mit ausstehender OCR und fehlgeschlagener Synchronisierung.\n",
  "文件字节合计不是 Android 系统的安装占用；不含 APK、系统配额或其他分区。目录仅可由本应用读取，不是共享相册。": "Die Dateibytes entsprechen nicht der Android-Installationsgröße; APKs, Systemkontingente und andere Partitionen sind ausgenommen. Die Verzeichnisse sind privat für diese App, keine gemeinsamen Alben.",
  "统计或队列暂不可读取，不能按零展示；原始文件保留，请查看支持诊断。": "Statistiken oder Warteschlange derzeit nicht lesbar; keine Null-Anzeige möglich. Originale bleiben erhalten. Prüfen Sie die Support-Diagnose.",
  "本机保留记录（第 {0} 页，每页 10 条；图片与文字请打开采集记录）": "Lokal behaltene Aufzeichnungen (Seite {0}, 10 pro Seite; Bilder und Texte unter „Erfassungsaufzeichnungen“)",
  "中央不可更新": "Zentrale Aufzeichnung nicht schreibbar",
  "已同步保留": "Synchronisiert und behalten",
  "媒体状态": "Medienstatus",
  "记录 ID：{0}\n创建：{1}\n条目字节：{2}\n本机仍保留此记录；下方历史同一 ID 可关联上传失败和确认。图片与文字可从采集记录查看。": "Aufzeichnungs-ID: {0}\nErstellt: {1}\nEintragsbytes: {2}\nDiese Aufzeichnung bleibt lokal. Ordnen Sie ihre ID dem Verlauf der Fehler und Bestätigungen unten zu. Bilder und Texte finden Sie unter „Erfassungsaufzeichnungen“.",
