  "来源限制与同步说明": "Quellenlimits und Synchronisierung",
  "来源说明": "Über Quellen",
  "默认扩展名 md/txt/json/csv/ics，正文只接受 UTF-8；单文件 100 KiB、100000 字符，单次最多 200 项和 4 MiB，来源缓存最多 64 MiB（也遵守采集与存储中的队列上限）。超限或扫描不完整会提示，绝不把漏扫项当作删除。\n系统后台任务约每 15 分钟检查一次来源各自的间隔；省电或强行停止可能推迟，重新打开应用可恢复。原件归档每文件最多 512 MiB，Mote 文件暂存最多 1 GiB；自动等待稳定后上传，断网续传。引用模式不读取原件，不受原件大小限制。": "Standarderweiterungen: md/txt/json/csv/ics, nur UTF-8-Text. Limits: 100 KiB/100000 Zeichen pro Datei; 200 Einträge/4 MiB pro Scan; 64 MiB Quellen-Cache, zusätzlich durch die Warteschlangenkapazität begrenzt. Überschreitungen und unvollständige Scans werden gemeldet; verpasste Einträge werden nie als gelöscht angesehen.\nHintergrundaufgaben prüfen die Quellenintervalle etwa alle 15 Minuten. Energiesparen oder erzwungenes Beenden kann sie verzögern; erneutes Öffnen der App stellt sie wieder her. Originalarchive erlauben 512 MiB pro Datei und 1 GiB Zwischenspeicher, warten auf stabile Dateien und setzen Uploads nach Verbindungsabbrüchen fort. Der Referenzmodus liest keine Originale und hat kein Limit für die Originalgröße.",
