  "首次清点后仅同步新条目": "Nach dem ersten Abgleich nur neue Einträge synchronisieren",
  "本地删除不影响中央原件；上传后仅清理 Mote 暂存，保留手机原文件。仅同步新增以首次完整清单为基线，重启不会重置。": "Lokales Löschen beeinflusst die zentralen Originale nicht. Die Upload-Bereinigung entfernt nur Mote-Zwischenspeicher und behält die Originale auf dem Telefon. Die Nur-neu-Synchronisierung nutzt den ersten vollständigen Abgleich als Basis; ein Neustart setzt sie nicht zurück.",
  "扫描间隔 / 分钟（15–1440，系统可能推迟）": "Scan-Intervall / Minuten (15–1440; System kann verzögern)",
