  "排除相对路径：每行一项，* 表示任意字符；区分大小写": "Ausgeschlossene relative Pfade: einer pro Zeile; * steht für beliebige Zeichen; Groß-/Kleinschreibung beachten",
  "更改选择、过滤或保留方式会清除这个来源的本机旧待发缓存，按新设置重新扫描；不会自动删除中央历史。停用仅暂停本机检查与同步，中央的启用状态与历史保持不变。移除只影响本机连接。": "Änderungen an Auswahl, Filtern oder Aufbewahrung löschen den alten lokalen Sende-Cache dieser Quelle und scannen mit den neuen Einstellungen erneut. Der zentrale Verlauf wird nicht gelöscht. Deaktivieren pausiert nur lokale Prüfungen und Synchronisierung. Entfernen betrifft nur die lokale Verbindung.",
