  "所选文件暂不可用；不会把访问失败视为删除": "Ausgewählte Datei derzeit nicht verfügbar; ein Zugriffsfehler gilt nicht als Löschung",
  "文件提供者不可用": "Dateianbieter nicht verfügbar",
  "从上传资料和持续采集中发现安排，逐条核对后添加到你选择的已有日历。备注附加 #Mote 来源标记。": "Erkennen Sie Termine in Uploads und erfasstem Kontext, prüfen Sie jeden einzeln und fügen Sie ihn einem gewählten vorhandenen Kalender hinzu; an die Notiz wird eine #Mote-Quellenmarkierung angehängt.",
  "首次使用：在中央网页「行动」开启发现，并授权此设备查看跨来源的建议及原文片段。": "Erste Nutzung: Aktivieren Sie die Erkennung und autorisieren Sie dieses Gerät in den zentralen „Aktionen“-Einstellungen, um quellenübergreifende Vorschläge und Originalauszüge anzuzeigen.",
  "刷新并同步已确认日程": "Aktualisieren und bestätigte Termine synchronisieren",
  "已刷新。每条日程需要确认后才写入。": "Aktualisiert. Jeder Termin muss vor dem Schreiben bestätigt werden.",
