  "正在连接日历…": "Kalender werden verbunden…",
  "正在同步已确认日程…": "Bestätigte Termine werden synchronisiert…",
  "尚未发现日程。上传资料或继续采集后会自动分析。": "Noch keine Termine erkannt. Die Analyse läuft nach Uploads oder weiterer Erfassung automatisch.",
  "等待保存回执": "Warten auf Speicherbestätigung",
  "已添加 · #Mote": "Hinzugefügt · #Mote",
