  "请先连接本机日历，并在系统日历中添加可写账户": "Verbinden Sie zuerst lokale Kalender und fügen Sie im Systemkalender ein beschreibbares Konto hinzu",
  "点击日期字段选择时间。全天日程的结束日期不包含当天。时区可修改。": "Tippen Sie auf Datumsfelder, um Zeiten zu wählen. Bei ganztägigen Terminen ist das Enddatum exklusiv. Die Zeitzone kann angepasst werden.",
  "夏令时切换时间不明确，请改用 UTC 时区": "Mehrdeutiger Sommerzeitwechsel. Verwenden Sie stattdessen UTC.",
