  "本机存储应用空间": "Lokaler App-Speicher",
  "所选存储介质不可用，请重新连接；不会切换为空目录": "Ausgewählter Speicher nicht verfügbar. Verbinden Sie ihn erneut; es wird nicht zu einem leeren Verzeichnis gewechselt.",
