  "投屏授权已结束（锁屏、系统或用户停止），请打开应用重新授权": "Autorisierung der Bildschirmfreigabe beendet (Sperrbildschirm, System oder Benutzerstopp). Öffnen Sie die App, um sie erneut zu erteilen.",
  "已锁屏，投屏采集结束；解锁后请重新授权": "Bildschirm gesperrt; Bildschirmfreigabe beendet. Autorisieren Sie nach dem Entsperren erneut.",
