  "日志读取失败，请重试；原文件保留。": "Logs konnten nicht gelesen werden. Erneut versuchen; die Originaldatei bleibt erhalten.",
  "投屏会话已结束，请点击开始并重新授权；已有记录保留，同步按所选策略运行": "Bildschirmfreigabe-Sitzung beendet. Starten Sie erneut und erteilen Sie die Berechtigung; vorhandene Aufzeichnungen bleiben erhalten und folgen Ihrer Synchronisierungsrichtlinie.",
  "上次同步已中断，记录保留在本机": "Die letzte Synchronisierung wurde unterbrochen. Aufzeichnungen bleiben auf diesem Gerät.",
  "请检查所选存储介质，保留应用数据": "Prüfen Sie den gewählten Speicher und behalten Sie die App-Daten.",
  "本地队列无法读取：{0}": "Lokale Warteschlange kann nicht gelesen werden: {0}",
  "扫描中央节点生成的连接二维码\n仅用于本次扫码；画面不保存、不上传。返回可用粘贴或 JSON 文件连接。": "Scannen Sie den Verbindungs-QR-Code Ihres zentralen Knotens\nDie Kamera wird nur zum Scannen verwendet; Bilder werden weder gespeichert noch hochgeladen. Sie können stattdessen auch eine Einladung einfügen oder JSON importieren.",
  "将二维码放入取景框": "QR-Code im Sucher positionieren",
  "本机图片数量正在读取": "Lokale Bildanzahl wird gelesen",
  "本机图片数量暂不可读取": "Lokale Bildanzahl derzeit nicht verfügbar",
  "当前图片 {0} 张 · 采集区 {1} 张 · 待决定区 {2} 张": "{0} Bilder · {1} erfasst · {2} zur Prüfung ausstehend",
