  "\n采集区图片文件 {0} 个 · 待决定区图片文件 {1} 个": "\n{0} erfasste Bilddateien · {1} Bilddateien zur Prüfung ausstehend",
  "\n本机队列 {0} · OCR 预留 {1} · 待决定区 {2}": "\nLokale Warteschlange {0} · OCR reserviert {1} · Zur Prüfung ausstehend {2}",
  "正在恢复本机存储": "Lokaler Speicher wird wiederhergestellt",
  "本机状态暂不可读取": "Lokaler Status derzeit nicht verfügbar",
