  "不支持的配置格式或版本": "Nicht unterstütztes Konfigurationsformat oder nicht unterstützte Version",
  "配置包含未知字段": "Konfiguration enthält unbekannte Felder",
  "模型配置包含未知字段": "Modellkonfiguration enthält unbekannte Felder",
  "{0} 必须为文本": "{0} muss Text sein",
  "{0} 必须为布尔值": "{0} muss ein boolescher Wert sein",
  "{0} 必须为整数": "{0} muss eine Ganzzahl sein",
  "本机文件类型无效，原文件已保留": "Ungültiger lokaler Dateityp; das Original wurde beibehalten",
  "本机文件格式升级失败，原文件已保留": "Aktualisierung des lokalen Formats fehlgeschlagen; das Original wurde beibehalten",
  "无障碍采集暂不可用，下一周期重试": "Erfassung über Bedienungshilfen ist nicht verfügbar; erneuter Versuch im nächsten Zyklus",
  "无障碍服务中断，请检查系统设置": "Bedienungshilfen-Dienst unterbrochen; prüfen Sie die Systemeinstellungen",
  "通知权限已关闭，为保持采集可见已停止，请授权通知后重新开始": "Erfassung gestoppt, da die Benachrichtigungsberechtigung deaktiviert ist. Erteilen Sie die Berechtigung und starten Sie erneut, um die Erfassung sichtbar zu halten.",
  "此系统需投屏模式采集内容；仅应用活动无需截图API": "Die Inhaltserfassung erfordert auf diesem System Bildschirmfreigabe; für reine App-Aktivität sind keine Screenshot-APIs erforderlich.",
  "系统未提供截图（代码 {0}），可能是安全窗口或权限变化；未保存内容": "Das System hat keinen Screenshot bereitgestellt (Code {0}), möglicherweise wegen eines geschützten Fensters oder einer Berechtigungsänderung. Es wurde kein Inhalt gespeichert.",
  "无障碍服务未连接，等待系统恢复或打开设置重新启用": "Bedienungshilfen-Dienst getrennt. Warten Sie auf die Wiederherstellung oder aktivieren Sie ihn erneut in den Einstellungen.",
  "{0} 条记录需要处理（冲突或中央不可用） · 待发 {1} 条；请打开同步与恢复": "{0} Aufzeichnungen erfordern Aufmerksamkeit (Konflikt oder zentraler Knoten nicht verfügbar) · {1} ausstehend; öffnen Sie Synchronisierung und Wiederherstellung.",
  "{0} 个来源同步需要处理 · 待发 {1} 条；请在来源页面检查权限或连接": "{0} Quellen erfordern Aufmerksamkeit · {1} ausstehend; prüfen Sie Berechtigungen oder Verbindungen auf der Quellen-Seite.",
  "仍有 {0} 条待发及 {1} 项来源设置待确认；暂停或权限不可用的来源需恢复后同步": "{0} Aufzeichnungen und {1} Quelleneinstellungen erfordern noch Aufmerksamkeit; setzen Sie pausierte Quellen fort oder stellen Sie Berechtigungen wieder her, um zu synchronisieren.",
  "当前待发已确认 · {0} 张图片等待本机 OCR，完成后继续同步": "Ausstehende Aufzeichnungen bestätigt · {0} Bilder warten auf lokale OCR und werden danach synchronisiert.",
  "当前待发记录已获中央确认；这不表示两端保留数量相同": "Der zentrale Knoten hat alle ausstehenden Aufzeichnungen bestätigt; dies bedeutet nicht, dass beide Seiten dieselbe Anzahl behalten.",
  "审查 allow 必须是布尔值": "„allow“ der Überprüfung muss ein boolescher Wert sein",
  "允许响应必须显式包含 rectangles 数组（无敏感区用空数组）": "Eine „allow“-Antwort muss explizit ein „rectangles“-Array enthalten (leer, wenn keine sensiblen Bereiche vorhanden sind)",
  "图片去重诊断": "Diagnose der Bild-Deduplizierung",
  "仅保留开启诊断后命中的图片对。图片已完成隐私检查和遮罩，仅在本机保存，不会同步。": "Es werden nur Bildpaare behalten, die nach Aktivierung der Diagnose erkannt wurden. Die Bilder haben Datenschutzprüfungen und Maskierung durchlaufen; sie bleiben auf diesem Gerät und werden nie synchronisiert.",
  "最多 20 组、32 MiB，保存期限 24 小时。读取时清理过期记录；系统休眠可能延后后台清理。关闭诊断后清空。": "Bis zu 20 Paare und 32 MiB, 24 Stunden aufbewahrt. Abgelaufene Aufzeichnungen werden beim Lesen entfernt; der Ruhezustand des Systems kann die Hintergrundbereinigung verzögern. Beim Deaktivieren der Diagnose werden sie gelöscht.",
  "清空全部诊断图片": "Alle Diagnosebilder löschen",
  "本机保留 {0} 组去重诊断": "{0} lokale Deduplizierungs-Paare",
  "诊断已关闭，临时图片已清空。可在开发者选项中开启。": "Die Diagnose ist deaktiviert und temporäre Bilder wurden gelöscht. Aktivieren Sie sie in den Entwickleroptionen.",
  "暂无图片对。开启后，下一次采集到重复画面时会在这里显示。": "Noch keine Bildpaare. Nach der Aktivierung der Diagnose erscheint die nächste Duplikat-Erfassung hier.",
  "{0} · {1}\n哈希相似度 {2}\n{3}": "{0} · {1}\nHash-Ähnlichkeit {2}\n{3}",
  "诊断读取失败，请重试。采集队列不受影响。": "Diagnose konnte nicht gelesen werden. Erneut versuchen; die Erfassungswarteschlange ist nicht betroffen.",
  "正在删除临时图片…": "Temporäre Bilder werden gelöscht…",
  "临时图片删除失败，请重试。": "Temporäre Bilder konnten nicht gelöscht werden. Erneut versuchen.",
  "正在读取图片对…": "Bildpaar wird geladen…",
  "去重图片对": "Dedupliziertes Bildpaar",
  "删除这组图片": "Dieses Paar löschen",
  "档位：{0}\n依据：{1}": "Stufe: {0}\nGrundlage: {1}",
  "哈希相似度 {0}\n计算：1 − {1}/64；这是像素哈希指标，不是模型置信度或语义相似度。": "Hash-Ähnlichkeit {0}\nBerechnung: 1 − {1}/64. Dies misst Pixel-Hashes, nicht Modellkonfidenz oder semantische Ähnlichkeit.",
  "处理后基准图 · 上一次保留的非重复帧\n{0}": "Verarbeitete Referenz · Zuletzt beibehaltener nicht duplizierter Frame\n{0}",
  "处理后基准图": "Verarbeitete Referenz",
  "被去重图片 · 本次未进入图片上传队列\n{0}": "Dedupliziertes Bild · Nicht zur Bild-Upload-Warteschlange hinzugefügt\n{0}",
  "被去重图片": "Dedupliziertes Bild",
  "处理后图片：{0} × {1} px\n去重采样：{2} × {3} px\n缩略比较网格：32 × 32；区块：8 × 8。": "Verarbeitetes Bild: {0} × {1} px\nDeduplizierungs-Stichprobe: {2} × {3} px\nMiniatur-Raster: 32 × 32; Blöcke: 8 × 8.",
  "图片已过期、已删除或暂时无法读取。请关闭后刷新列表。": "Bilder sind abgelaufen, wurden gelöscht oder sind nicht verfügbar. Schließen Sie diese Ansicht und aktualisieren Sie die Liste.",
  "哈希距离：{0} / 阈值 {1}\n": "Hash-Abstand: {0} / Schwellenwert {1}\n",
  "缩略图变化像素：{0} / 阈值 {1}\n": "Geänderte Miniatur-Pixel: {0} / Schwellenwert {1}\n",
