  "\n本次由像素哈希一致直接命中，未进入近似阈值判断。": "\nIdentische Pixel-Hashes trafen direkt zu; Näherungsschwellenwerte wurden nicht ausgewertet.",
  "\n基准采集 ID：{0}\n本次采集 ID：{1}": "\nReferenz-Erfassungs-ID: {0}\nAktuelle Erfassungs-ID: {1}",
  "\n应用：{0}": "\nApp: {0}",
  "OCR 模式无效": "Ungültiger OCR-Modus",
  "下载未完成，将退避重试；可取消后更换来源，已有断点保留": "Download unvollständig; erneuter Versuch mit Backoff. Abbrechen, um Quellen zu wechseln; heruntergeladene Daten bleiben erhalten.",
  "下载已暂停，断点保留；点击下载/继续可恢复": "Download pausiert; der Fortschritt bleibt erhalten. Tippen Sie auf Herunterladen / Fortsetzen, um fortzufahren.",
  "等待符合网络设置的连接，准备下载/续传": "Warten auf eine Verbindung, die den Netzwerkeinstellungen entspricht, um herunterzuladen oder fortzusetzen",
  "通知事件已启用": "Benachrichtigungsereignisse aktiviert",
  "亮屏与锁定事件已启用": "Bildschirm- und Sperrereignisse aktiviert",
