  "模型配置管理": "Modellprofile",
  "模型配置与分工": "Modellprofile und Zuweisungen",
  "可以保存多个服务商，也可以为同一服务商保存不同模型。每次请求的选择优先于功能默认值。": "Speichern Sie mehrere Anbieter oder verschiedene Modelle desselben Anbieters. Eine Auswahl pro Anfrage setzt Funktionsstandards außer Kraft.",
