  "新增配置": "Profil hinzufügen",
  "删除配置": "Profil löschen",
  "删除这套模型配置及凭据？已保存的问答保留。": "Dieses Modellprofil und seine Anmeldedaten löschen? Gespeicherte Unterhaltungen bleiben erhalten.",
  "各功能默认模型": "Standardmodell nach Funktion",
  "默认模型": "Standardmodell",
  " · 未配置": " · Nicht konfiguriert",
  "保存功能默认值": "Funktionsstandards speichern",
  "本次模型": "Modell für diese Anfrage",
  "功能默认": "Funktionsstandard",
  "配置已不可用，请重新选择": "Profil nicht verfügbar; wählen Sie ein anderes",
  "无法读取模型列表：": "Modellliste kann nicht geladen werden: ",
  "模型配置已被删除，请重新选择。": "Dieses Modellprofil wurde gelöscht. Wählen Sie ein anderes.",
  "默认项已恢复部署配置，功能分配保持不变。": "Das Standardprofil wurde auf die Bereitstellungseinstellungen zurückgesetzt; Funktionszuweisungen bleiben unverändert.",
  "已保存。选择此配置的新请求将立即使用这些设置。": "Gespeichert. Neue Anfragen mit diesem Profil verwenden diese Einstellungen sofort.",
  "每套配置独立保存服务、模型和凭据；在功能入口或默认分配中选择。": "Jedes Profil speichert eigenen Anbieter, Modell und Anmeldedaten. Wählen Sie es an einem Funktionseinstiegspunkt oder in Standardzuweisungen.",
  "配置名称": "Profilname",
  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex 仍会将选中的上下文发送到其模型服务；最长等待时间生效，输出 token 上限由 Codex 管理。": "Verwendet dateibasierte Codex-CLI-Anmeldedaten auf dem zentralen Server. Hier ist kein API-Schlüssel erforderlich. Codex sendet den ausgewählten Kontext weiterhin an seinen Modelldienst. Das Zeitlimit gilt; Codex verwaltet das Limit der Ausgabetokens.",
  "Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Codex Server verwaltet einzelne Modellgenerierungsanfragen innerhalb von App Server; das „Zeitlimit für einzelne Modellanfragen“ der Seite gilt nicht für die interne Generierung. „Gesamtlaufzeit-Zeitlimit des Agents“ kann leer bleiben, wodurch Motes Gesamtlaufzeitgrenze deaktiviert wird. Codex verwaltet das Limit der Ausgabetokens.",
  "输出由 Codex 管理": "Ausgabe wird von Codex verwaltet",
  "{0} / {1} 秒": "{0} / {1} Sekunden",
  "{0}；单次模型请求 {1} 秒；Agent 总运行 {2} 秒": "{0}; einzelne Modellanfrage {1} Sekunden; Gesamtlaufzeit des Agents {2} Sekunden",
  "将默认配置恢复为中央节点的启动环境或部署配置，其他配置和功能分配保留。当前未保存的草稿也会清空；不会修改部署文件。": "Stellt das Standardprofil aus der Startumgebung oder Bereitstellungskonfiguration des zentralen Knotens wieder her. Andere Profile und Funktionszuweisungen bleiben erhalten. Ungespeicherte Entwürfe werden gelöscht; Bereitstellungsdateien werden nicht geändert.",
  "所选模型配置不存在，请重新选择。": "Das ausgewählte Modellprofil existiert nicht. Wählen Sie ein anderes.",
  "该配置仍是某项功能的默认模型，请先修改功能默认值。": "Dieses Profil ist noch Standard einer Funktion. Ändern Sie zuerst den Funktionsstandard.",
  "Chat 问答": "Chat",
  "Memory 记忆提取": "Memory-Extraktion",
  "资料导入": "Inhaltsimport",
  "文件分析": "Dateianalyse",
  "本机 Codex": "Lokaler Codex",
  "通过中央服务器上的 Codex App Server 调用已登录账户。推理仍由 Codex 服务完成；需安装 Codex CLI 并在服务器登录。": "Ruft das angemeldete Konto über den Codex App Server auf dem zentralen Server auf. Die Inferenz läuft weiterhin über den Codex-Dienst. Installieren Sie zuerst die Codex CLI und melden Sie sich auf dem Server an.",
