  "需要 macOS 辅助功能授权。仅记录系统当前公开的通知视图，无法读取未展示或已消失的通知。启用应用排除或仅活动规则时暂停此功能。": "Erfordert Zugriff auf die macOS-Bedienungshilfen. Es werden nur aktuell sichtbare Mitteilungsansichten aufgezeichnet; ausgeblendete oder entfernte Mitteilungen sind nicht verfügbar. Bei App-Ausschlüssen oder Nur-aktiv-Regeln pausiert diese Funktion.",
