  "副本独立保存。修改副本不会影响原预设；更换地址时仍需确认凭据复用。": "Die Kopie ist unabhängig. Änderungen wirken sich nicht auf das Original aus. Beim Ändern des Endpunkts ist weiterhin eine Bestätigung zur Wiederverwendung der Zugangsdaten erforderlich.",
