  "删除这套预设及凭据？历史问答保留。": "Diese Voreinstellung und ihre Zugangsdaten löschen? Bisherige Unterhaltungen bleiben erhalten.",
  "部署配置": "Bereitstellungskonfiguration",
  "来自本次启动读取的配置文件或环境变量。修改文件后重启生效；需要在页面调整时，请先复制为独立预设。": "Beim Start aus der Konfigurationsdatei oder Umgebung geladen. Nach dem Bearbeiten der Datei neu starten. Um hier Änderungen vorzunehmen, kopieren Sie sie zuerst als eigenständige Voreinstellung.",
