  "使用本机 Codex 的登录账户加载目录，并通过 Codex App Server 调用所选模型。": "Lädt den Katalog über das lokale Codex-Konto und ruft das ausgewählte Modell über den Codex App Server auf.",
  "留空表示此预设尚未就绪。": "Leer lassen, damit diese Voreinstellung unkonfiguriert bleibt.",
