  "连接预设、模型目录、凭据与测试": "Verbindungsvoreinstellungen, Modellkataloge, Zugangsdaten und Tests",
  "模块与模型": "Module und Modelle",
  "为各模块分配预设和模型，设置记忆与回顾": "Module den Voreinstellungen und Modellen zuweisen; Erinnerung und Überprüfungen konfigurieren",
  "旧版默认预设": "Legacy-Standardvoreinstellung",
  "部署配置为只读，请复制为新预设后编辑。": "Die Bereitstellungskonfiguration ist schreibgeschützt. Kopieren Sie sie zum Bearbeiten in eine neue Voreinstellung.",
  "中央节点 · 已连接": "Zentraler Knoten · Verbunden",
  "中央节点 · 正在验证": "Zentraler Knoten · Wird überprüft",
  "已连接中央节点，打开连接详情": "Zentraler Knoten verbunden. Verbindungsdetails öffnen",
  "中央节点连接": "Verbindung zum zentralen Knoten",
  "中央节点连接状态": "Status der Verbindung zum zentralen Knoten",
  "未连接中央节点": "Nicht mit dem zentralen Knoten verbunden",
  "正在同步中央节点": "Synchronisierung mit dem zentralen Knoten",
  "连接需要处理": "Verbindung erfordert Aufmerksamkeit",
  "记录只保存在本机；连接后按你的策略上传。": "Aufzeichnungen bleiben auf diesem Gerät, bis Sie eine Verbindung herstellen; dann werden sie gemäß Ihren Synchronisierungseinstellungen hochgeladen.",
