  "查看连接": "Verbindung anzeigen",
  "连接设置": "Verbindungseinstellungen",
  "正在读取保存的连接与同步状态…": "Gespeicherte Verbindung und Synchronisierungsstatus werden gelesen…",
  "{0} 条记录等待中央确认 · 节点：{1}": "{0} Aufzeichnungen warten auf zentrale Bestätigung · Knoten: {1}",
  "节点已保存，但尚未完成最近一次连接验证：{0}": "Knoten gespeichert, aber die letzte Verbindungsprüfung wurde nicht abgeschlossen: {0}",
  "节点：{0} · 最近一次验证成功": "Knoten: {0} · Letzte Prüfung erfolgreich",
  "你的个人上下文助手": "Ihr persönlicher Kontext-Assistent",
  "这次回答没有完成": "Diese Antwort wurde nicht abgeschlossen",
  "再次提问": "Erneut fragen",
  "Enter 发送 · Shift+Enter 换行": "Eingabetaste zum Senden · Umschalt+Eingabetaste für eine neue Zeile",
  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Verwendet die dateibasierten Anmeldedaten der Codex CLI auf dem zentralen Server. Hier ist kein API-Schlüssel erforderlich. Codex Server verwaltet einzelne Modellanfragen intern im App Server; das Zeitlimit für einzelne Modellanfragen gilt nicht für die interne Generierung. Das Gesamtlaufzeit-Zeitlimit des Agenten kann leer bleiben. Codex verwaltet das Ausgabe-Token-Limit.",
  "HTTP Provider：单次模型 API 请求的期限，包含一次生成和流式响应，不包含后续工具循环。Codex Server 不暴露内部单次模型请求，此项不适用。": "HTTP-Anbieter: das Zeitlimit für eine Modell-API-Anfrage, einschließlich einer Generierung und gestreamter Antwort, aber ohne spätere Tool-Schleifen. Codex Server macht einzelne Modellanfragen nicht sichtbar; dies gilt nicht.",
  "从一次 Agent 运行开始到完成，包含多次模型请求、工具调用和结果校验。Codex Server 可留空，留空表示不设置 Mote 的总运行期限。": "Vom Start eines Agentenlaufs bis zum Abschluss, einschließlich mehrerer Modellanfragen, Tool-Aufrufe und Ergebnisvalidierung. Codex Server kann dies leer lassen, um das Gesamtlaufzeit-Limit von Mote zu deaktivieren.",
  "已保存节点 · 待验证": "Gespeicherter Knoten · Überprüfung ausstehend",
  "已连接中央节点": "Mit dem zentralen Knoten verbunden",
  "请输入有效的中央所有者令牌": "Geben Sie ein gültiges zentrales Eigentümer-Token ein",
  "问一问需要中央所有者令牌；设备采集凭据不能读取个人归档。": "„Fragen“ erfordert ein zentrales Eigentümer-Token; Erfassungs-Anmeldedaten des Geräts können Ihr Archiv nicht lesen.",
  "请输入问题（最多 8000 字）": "Geben Sie eine Frage ein (bis zu 8.000 Zeichen)",
  "问一问需要有效的中央所有者令牌，请重新登录。": "„Fragen“ erfordert ein gültiges zentrales Eigentümer-Token. Bitte melden Sie sich erneut an.",
  "问答请求失败（HTTP {0}），请检查中央节点模型设置或稍后重试。": "Anfrage von „Fragen“ fehlgeschlagen (HTTP {0}). Prüfen Sie die zentralen Modelleinstellungen oder versuchen Sie es später erneut.",
  "中央记录冲突或已删除，本机副本保留待处理。": "Die zentrale Aufzeichnung steht in Konflikt oder wurde gelöscht. Die lokale Kopie bleibt zur Überprüfung erhalten.",
