  "丢弃修改": "Änderungen verwerfen",
  "控制与保护": "Kontrolle & Schutz",
  "隐私与权限": "Datenschutz & Berechtigungen",
  "本机状态详情": "Details zum lokalen Status",
  "打开中央工作台": "Zentralen Arbeitsbereich öffnen",
  "依赖步骤未完成，请先检查上游任务": "Abhängigkeit unvollständig; prüfen Sie die vorgelagerte Aufgabe",
  "处理器版本不可用": "Prozessorversion nicht verfügbar",
  "运行中断，等待恢复": "Unterbrochen; wartet auf Wiederherstellung",
  "用户取消": "Vom Benutzer abgebrochen",
  "来源变化待重验": "Quelle geändert; Überprüfung erforderlich",
  "受阻": "Blockiert",
  "已注册的处理器及其版本。扩展由节点管理，不提供在线安装。": "Registrierte Prozessoren und Versionen. Erweiterungen werden vom Knoten verwaltet; eine Online-Installation ist nicht verfügbar.",
  "查看处理步骤、依赖与等待原因。重试保留其他已完成步骤。": "Schritte, Abhängigkeiten und Wartegründe prüfen. Ein erneuter Versuch behält andere abgeschlossene Schritte.",
  "重试此步骤": "Diesen Schritt erneut versuchen",
  "中央服务从源码部署，升级前先备份。当前不提供应用内自动更新。": "Den zentralen Dienst aus dem Quellcode bereitstellen und vor dem Upgrade ein Backup erstellen. Automatische In-App-Updates sind derzeit nicht verfügbar.",
  "来源资料": "Quellenaufzeichnungen",
  "浏览来源资料": "Quellenaufzeichnungen durchsuchen",
  "整理任务与排队（": "Verarbeitungsaufträge und Warteschlange (",
  "自动整理": "Automatisch verarbeiten",
  "手动整理": "Manuell verarbeiten",
