  "较长时间未收到新活动；任务仍在等待，不代表已有新结果。": "Keine aktuelle Aktivität. Die Aufgabe wartet noch; ein neues Ergebnis wird nicht impliziert.",
  "继续整理": "Verarbeitung fortsetzen",
  "取消剩余批次": "Verbleibende Stapel abbrechen",
