  " · 候选 {0}": " · Kandidat {0}",
  " · 引用 {0}": " · Zitat {0}",
  "等待自动重试": "Warten auf automatischen Wiederholungsversuch",
  "排队等待执行名额": "In Warteschlange für Ausführungskapazität",
  "正在执行": "Wird ausgeführt",
  "失败，等待重试": "Fehlgeschlagen, Wiederholung ausstehend",
  "已保存，立即生效。": "Gespeichert und sofort angewendet.",
  "执行并发": "Ausführungs-Parallelität",
  "保存后立即生效，重启后保留。": "Änderungen gelten sofort und bleiben nach einem Neustart erhalten.",
  "超出名额的工作会排队。降低上限不会中断正在执行的任务。LLM 名额覆盖一次模型运行及其工具循环；Codex 内部请求不可单独计量。": "Arbeit, die die Kapazität überschreitet, wird eingereiht. Das Senken der Limits unterbricht laufende Arbeit nicht. Die LLM-Kapazität deckt eine Modellsitzung und ihre Tool-Schleife ab; interne Codex-Anfragen können nicht einzeln gemessen werden.",
  "详细过程与运行日志使用相同的 JSON 行格式，包含 prompt、上下文、模型输出和工具过程，可能包含个人内容。关闭后立即停止新增详细记录。": "Detaillierte Traces verwenden dasselbe JSON-Lines-Format wie Laufzeitprotokolle und enthalten Prompts, Kontext, Modellausgabe und Tool-Aktivität, die persönliche Inhalte enthalten können. Deaktivieren stoppt neue detaillierte Traces sofort.",
  "执行队列": "Ausführungswarteschlangen",
  "Agent：执行中 {0} / {1}，排队 {2}": "Agent: {0} / {1} laufen, {2} in Warteschlange",
  "LLM：执行中 {0} / {1}，排队 {2}": "LLM: {0} / {1} laufen, {2} in Warteschlange",
  "等待模型执行名额": "Warten auf Modellkapazität",
  "模型处理中": "Modellverarbeitung läuft",
  "等待 Agent 执行名额": "Warten auf Agent-Kapazität",
  "Agent 并发": "Agent-Parallelität",
  "运行中的 Agent 上限；可在设置中立即调整。": "Maximal laufende Agenten; Änderungen in den Einstellungen gelten sofort.",
  "LLM 执行并发": "LLM-Ausführungsparallelität",
  "模型运行及工具循环的并发上限。": "Parallele Modellsitzungen einschließlich ihrer Tool-Schleifen.",
  "记忆批次并发": "Parallelität der Erinnerungsstapel",
  "独立证据批次的并发上限。": "Maximale parallele unabhängige Nachweisstapel.",
  "先检索 memories 的精选记忆概览，再按需展开相关记忆、observation 和 segments。Memory 未命中不代表原始事件不存在；参考整理覆盖信息，用 changes 的 overview 或全文检索发现尚未整理的增量。只对有意义的发现选择性读取原始证据，核实最终报告的事实、数字、归属和时间。不要穷尽读取本窗口全部原文；预算不足时用已有证据生成范围明确的部分报告，说明未覆盖内容。注意迟到上传、修订、人物归属、偏好变化及计划的未知结果。没有支持时明确说明信息不足。不要声称完整回顾了全部历史。未设置时间过滤，允许跨月检索。": "Durchsuchen Sie zuerst die Übersichten ausgewählter Erinnerungen und erweitern Sie dann bei Bedarf relevante Erinnerungen, Beobachtungen und Segmente. Eine fehlende Erinnerung bedeutet kein fehlendes Ereignis. Nutzen Sie die Verarbeitungsabdeckung, Änderungsübersichten oder die Textsuche, um unverarbeitete Neueingänge zu finden. Lesen Sie Originale gezielt, um Fakten, Zahlen, Zuschreibungen und Zeiten des Berichts zu verifizieren. Lesen Sie dieses Fenster nicht erschöpfend. Bei begrenztem Budget liefern Sie einen Teilbericht mit expliziter Abdeckung. Berücksichtigen Sie verspätete Uploads, Revisionen, Zuschreibungen, sich ändernde Präferenzen und unbekannte Ergebnisse. Geben Sie unzureichende Nachweise an, wo angemessen. Behaupten Sie nicht, den gesamten Verlauf überprüft zu haben. Es gibt keinen Zeitfilter; Suchen können sich über Monate erstrecken.",
  "Gmail 已连接。请返回 Mote 同步邮件。": "Gmail verbunden. Kehren Sie zu Mote zurück, um E-Mails zu synchronisieren.",
  "连接 Gmail（只读）": "Gmail verbinden (schreibgeschützt)",
  "同步邮件正文、发件人和时间，附件仅保留名称与引用。邮件内容作为资料，不自动执行其中的指令。断开后停止读取，已归档邮件保留。": "Nachrichtentext, Absender und Zeitstempel synchronisieren. Anhänge behalten nur Namen und Referenzen. Nachrichten sind Nachweise; ihre Anweisungen werden nie automatisch ausgeführt. Das Trennen stoppt die Erfassung und bewahrt archivierte Nachrichten.",
  "Gmail 使用现有 Google OAuth 客户端与回调地址。请在 Google Cloud 启用 Gmail API，再到模型与服务配置客户端。": "Gmail verwendet den vorhandenen Google-OAuth-Client und Callback. Aktivieren Sie die Gmail API in Google Cloud und konfigurieren Sie dann den Client unter „Modelle & Dienste“.",
  "历史邮件仍有后续分页": "Es verbleiben weitere ältere Nachrichten",
  " 后续邮件将在下一轮继续同步。": " Verbleibende Nachrichten werden in den nächsten Runden synchronisiert.",
  "继续同步": "Synchronisierung fortsetzen",
  "尚未启用 MCP。请在系统管理 → 模型与服务 → 来源与外部应用中开启 MCP，并配置独立读令牌后重启；写入还需明确启用并设置允许的信源。": "MCP ist deaktiviert. Aktivieren Sie es unter System → Modelle & Dienste → Quellen & externe Apps, konfigurieren Sie ein separates Lese-Token und starten Sie neu. Schreiben erfordert eine explizite Aktivierung und erlaubte Quellen.",
  "请先在系统管理 → 模型与服务 → 来源与外部应用中准备 Google OAuth 客户端与回调地址，然后重启节点。": "Konfigurieren Sie den Google-OAuth-Client und Callback unter System → Modelle & Dienste → Quellen & externe Apps und starten Sie dann den Knoten neu.",
  "。配置入口在“系统管理 → 模型与服务 → 来源与外部应用”。仅支持 OAuth 的 Chatbot 不能直接使用 Bearer 接入。": ". Konfigurieren Sie dies unter System → Modelle & Dienste → Quellen & externe Apps. Chatbots, die nur OAuth unterstützen, können nicht direkt mit Bearer-Tokens verbunden werden.",
  "原件资产目录": "Original-Asset-Verzeichnis",
  "图片、导入文件与目录原件按内容哈希共享分片；观察记录和来源版本各自保留。": "Bilder, importierte Dateien und Verzeichnisoriginale teilen inhaltsadressierte Teile; Beobachtungen und Quellversionen behalten eigene Identitäten.",
  "限制去重原件、记录和处理元数据的逻辑字节；SQLite 索引、WAL、日志等额外占盘。达到上限返回 507，端点保留待传队列。": "Begrenzt die logischen Bytes für deduplizierte Originale, Aufzeichnungen und Verarbeitungsmetadaten; SQLite-Indizes, WAL und Protokolle belegen zusätzlichen Platz. Bei voller Kapazität antwortet der Server mit 507 und Clients behalten ihre ausstehenden Warteschlangen.",
