  "无法连接处理服务，请检查网络与服务地址。": "Keine Verbindung zum Verarbeitungsdienst möglich. Prüfen Sie Netzwerk und Endpunkt.",
  "处理服务拒绝了内容大小，请缩小本次处理范围。": "Der Verarbeitungsdienst hat die Inhaltsgröße abgelehnt. Reduzieren Sie den Verarbeitungsumfang.",
