  "审核记录": "Überprüfungsverlauf",
  "复用了相同候选与证据版本的独立审核结果，并重新校验了引用和范围。": "Hat eine unabhängige Überprüfung der identischen Kandidaten- und Nachweisversionen wiederverwendet und anschließend Zitate und Umfang erneut validiert.",
  "候选已经过独立模型审核和引用校验；用户确认单独记录。": "Der Kandidat erhielt eine unabhängige Modellüberprüfung und Zitatprüfungen. Die Benutzerbestätigung wird separat aufgezeichnet.",
