  "已更新待确认的建议": "Vorschlag aktualisiert; Bestätigung ausstehend",
  "原安排": "Ursprüngliche Anordnung",
  "确认后仅在 Mote 中标记完成。": "Die Bestätigung markiert dies nur in Mote als abgeschlossen.",
  "确认后更新原建议；尚未写入系统日历。": "Die Bestätigung aktualisiert den Vorschlag; er wurde noch nicht zum Systemkalender hinzugefügt.",
  "确认后修改或取消原设备上的这一条日程；不会新建另一条日程。": "Die Bestätigung aktualisiert oder sagt diesen Termin auf seinem ursprünglichen Gerät ab, ohne einen weiteren Termin zu erstellen.",
  "保存后会交给该设备写入，备注中附加 #Mote 标记。不会邀请参与人。": "Nach dem Speichern schreibt dieses Gerät den Termin mit einer #Mote-Notiz. Es werden keine Teilnehmer eingeladen.",
  "确认变更": "Änderungen bestätigen",
  "资料已归档": "Material archiviert",
  "OCR、索引和记忆分别处理；处理进度请在任务中心查看。": "OCR, Indizierung und Erinnerung laufen separat. Deren Fortschritt sehen Sie unter Aufgaben.",
  "资料范围与覆盖": "Nachweisumfang und -abdeckung",
