  "所选时段包含未采样时间，结论只覆盖已有记录。": "Der gewählte Zeitraum enthält nicht erfasste Zeit. Schlussfolgerungen decken nur vorhandene Aufzeichnungen ab.",
  "部分资料仍未完成处理或仅保留来源引用，内容覆盖不完整。": "Einiges Material wird noch verarbeitet oder enthält nur Quellreferenzen. Die Inhaltsabdeckung ist unvollständig.",
  "此报告是同一范围的新版本，旧报告保留各自的资料快照。": "Dies ist eine neue Berichtsversion für denselben Umfang. Frühere Berichte behalten ihre eigenen Nachweis-Snapshots.",
  "包括已替代和过期的历史记忆": "Ersetzte und abgelaufene Erinnerungen einschließen",
  "查看当时有效的记忆": "Damals gültige Erinnerungen anzeigen",
  "回到当前": "Zurück zur aktuellen Version",
  "已由新版本替代": "Durch eine neue Version ersetzt",
