  "生效于": "Gültig ab",
  "失效于": "Gültig bis",
  "这是用户主动纠正并确认的版本，原始说明已保留。": "Diese Version wurde vom Benutzer ausdrücklich korrigiert und bestätigt. Die ursprüngliche Aussage bleibt erhalten.",
  "查看替代版本": "Ersatzversion anzeigen",
  "替代的旧记忆": "Zu ersetzende Erinnerung",
  "存在矛盾的记忆": "Widersprüchliche Erinnerung",
  "确认后才应用此关系，旧内容仍保留。": "Diese Beziehung gilt erst nach der Bestätigung. Frühere Inhalte bleiben erhalten.",
  "纠正并确认": "Korrigieren und bestätigen",
  "填写你确认的内容。它将作为你的原始说明保存，生成新版本；旧记忆及其证据仍可查看，适用项目保持不变。": "Geben Sie den Inhalt ein, den Sie bestätigen. Er wird als Ihre ursprüngliche Aussage gespeichert und erzeugt eine neue Version. Frühere Erinnerung und Nachweise bleiben verfügbar; der Projektumfang bleibt unverändert.",
  "你确认的内容": "Von Ihnen bestätigter Inhalt",
  "生效时间（留空为现在）": "Gültig ab (leer bedeutet jetzt)",
