  "中央处理状态待查询，请在中央任务中心查看": "Zentraler Verarbeitungsstatus unbekannt; prüfen Sie die zentralen Aufgaben",
  "关联日程已更新或正在执行，请刷新后重新确认": "Der verknüpfte Termin hat sich geändert oder wird verarbeitet. Aktualisieren Sie und bestätigen Sie erneut.",
