  "原日程已改变，请核实修改结果": "Der ursprüngliche Termin hat sich geändert. Prüfen Sie das Änderungsergebnis.",
  "请在原设备确认，或使用中央网页": "Auf dem ursprünglichen Gerät bestätigen oder die zentrale Webseite verwenden",
  "确认后取消原设备上的这一条日程。": "Die Bestätigung sagt diesen Termin auf dem ursprünglichen Gerät ab.",
  "确认后取消尚未写入日历的原建议。": "Die Bestätigung sagt den ursprünglichen Vorschlag ab, der noch nicht in den Kalender geschrieben wurde.",
  "正在确认变更…": "Änderungen werden bestätigt…",
  "仅更新原建议": "Nur den ursprünglichen Vorschlag aktualisieren",
  "确认后更新原日程，不新建另一条。": "Die Bestätigung aktualisiert den ursprünglichen Termin, ohne einen weiteren zu erstellen.",
  "确认后仅更新原建议，仍需确认添加到日历。": "Die Bestätigung aktualisiert nur den ursprünglichen Vorschlag. Das Hinzufügen zum Kalender erfordert weiterhin eine Bestätigung.",
  "模型服务额度不足，恢复账户额度后再继续。": "Das Kontingent des Modellanbieters ist erschöpft. Stellen Sie das Kontokontingent wieder her, bevor Sie fortfahren.",
  "模型服务拒绝了本次请求，请调整内容或处理范围。": "Der Modellanbieter hat diese Anfrage abgelehnt. Passen Sie deren Inhalt oder Umfang an.",
  "自动恢复时间已用完，可手动重试开启新的恢复周期。": "Das automatische Wiederherstellungsfenster ist abgelaufen. Versuchen Sie es manuell erneut, um ein neues Wiederherstellungsfenster zu starten.",
  "相关模型配置已改变，请重试以使用新配置；已完成批次会保留。": "Die relevante Modellkonfiguration hat sich geändert. Versuchen Sie es erneut, um sie zu verwenden; abgeschlossene Stapel bleiben erhalten.",
  "后台整理窗口": "Hintergrundverarbeitungsfenster",
  "行动分析": "Aktionsanalyse",
  "原始资料已变化，此结果不能发布，请重新处理。": "Die Quellnachweise haben sich geändert. Verarbeiten Sie sie erneut, bevor Sie dieses Ergebnis veröffentlichen.",
  "处理曾中断，请查看任务中心的恢复状态。": "Die Verarbeitung wurde unterbrochen. Prüfen Sie ihren Wiederherstellungsstatus unter Aufgaben.",
  "处理服务离线，请检查服务状态。": "Der Verarbeitungsdienst ist offline. Prüfen Sie dessen Status.",
  "当前连接没有访问权限。": "Diese Verbindung hat keinen Zugriff.",
  "操作未完成。错误码：{0}": "Der Vorgang wurde nicht abgeschlossen. Fehlercode: {0}",
  "模型服务地址不正确，请检查配置。": "Die Adresse des Modelldienstes ist falsch. Prüfen Sie dessen Konfiguration.",
  "模型服务暂时不可用，请检查服务配置。": "Der Modelldienst ist vorübergehend nicht verfügbar. Prüfen Sie dessen Konfiguration.",
  "模型服务暂时限流，请等待任务更新。": "Der Modelldienst begrenzt die Anfragen. Warten Sie auf die Aktualisierung der Aufgabe.",
  "模型服务未完成请求，请查看任务状态。": "Der Modelldienst hat die Anfrage nicht abgeschlossen. Prüfen Sie den Aufgabenstatus.",
  "模型服务认证失败，请检查凭据。": "Authentifizierung beim Modelldienst fehlgeschlagen. Prüfen Sie die Anmeldedaten.",
  "模型服务重定向未获允许，请检查地址配置。": "Die Weiterleitung des Modelldienstes ist nicht erlaubt. Prüfen Sie die Adresskonfiguration.",
  "模型服务额度不足，请补充额度后继续。": "Das Kontingent des Modelldienstes ist erschöpft. Stellen Sie das Kontingent wieder her, um fortzufahren.",
  "模型返回的结果未通过校验。": "Die Modellantwort hat die Validierung nicht bestanden.",
  "模型配置已变化，请在任务中心确认后继续；已完成的步骤会保留。": "Die Modellkonfiguration hat sich geändert. Bestätigen Sie unter Aufgaben, um fortzufahren; abgeschlossene Schritte bleiben erhalten.",
  "等待你确认后继续。": "Warten auf Ihre Bestätigung zum Fortfahren.",
  "自动恢复期限已结束，请在任务中心手动重试。": "Das automatische Wiederherstellungsfenster ist abgelaufen. Versuchen Sie es unter Aufgaben manuell erneut.",
  "访问凭据已失效，请重新连接。": "Die Zugangsdaten sind abgelaufen. Verbinden Sie sich erneut, um fortzufahren.",
  "请先完成模型配置。": "Schließen Sie zuerst die Modellkonfiguration ab.",
  "请求等待超时，请查看任务状态。": "Die Anfrage hat das Zeitlimit überschritten. Prüfen Sie den Aufgabenstatus.",
  "运行已中断，请查看历史结果后重新发起。": "Der Lauf wurde unterbrochen. Überprüfen Sie dessen Verlauf, bevor Sie einen neuen Lauf starten.",
  "连接暂时中断，请检查网络。": "Die Verbindung wurde unterbrochen. Prüfen Sie das Netzwerk.",
  "先检索 memories 的精选记忆概览，再按需展开相关记忆、observation 和 segments。Memory 未命中不代表原始事件不存在；参考整理覆盖信息，用 changes 的 overview 或全文检索发现尚未整理的增量。只对有意义的发现选择性读取原始证据，核实最终报告的事实、数字、归属和时间。不要穷尽读取本窗口全部原文；预算不足时用已有证据生成范围明确的部分报告，说明未覆盖内容。注意迟到上传、修订、人物归属、偏好变化及计划的未知结果。没有支持时明确说明信息不足。不要声称完整回顾了全部历史。按照宿主固定范围检索，允许范围内跨月检索。": "Durchsuchen Sie zuerst die Übersicht kuratierter Erinnerungen und erweitern Sie dann bei Bedarf relevante Erinnerungen, Beobachtungen und Segmente. Eine fehlende Erinnerung bedeutet nicht, dass das ursprüngliche Ereignis fehlt; nutzen Sie die Organisationsabdeckung und die Änderungsübersicht oder die Volltextsuche, um unverarbeitete Zugänge zu finden. Lesen Sie Originalnachweise gezielt für bedeutsame Funde, um Fakten, Zahlen, Zuschreibungen und Zeiten zu verifizieren. Lesen Sie nicht erschöpfend jedes Original in diesem Fenster. Reicht das Budget nicht, erstellen Sie einen klar begrenzten Teilbericht aus verfügbaren Nachweisen und geben Sie an, was unabgedeckt bleibt. Berücksichtigen Sie verspätete Uploads, Revisionen, Zuschreibungen, Präferenzänderungen und unbekannte Ergebnisse von Plänen. Geben Sie an, wenn Nachweise unzureichend sind. Behaupten Sie nicht, den gesamten Verlauf überprüft zu haben. Folgen Sie dem vom Host definierten Umfang; Suchen dürfen sich darin über Monate erstrecken.",
