  "本地转写与说话人模型：": "Lokales Transkriptions- und Sprechermodell:",
  "读取中": "Wird geladen",
  "转写与说话人 Worker 已就绪": "Transkriptions- und Sprecher-Worker ist bereit",
  "模型已安装，等待音频 Worker 启动或安装 Native 运行时": "Modell installiert; warten auf den Start des Audio-Workers oder die Installation der nativen Laufzeit",
  "下载并安装本地音频模型": "Lokales Audiomodell herunterladen und installieren",
  "新上传录音默认在中央转写并区分匿名说话人；模型未就绪时先归档。单文件时长可在下方设置，不设每日限额。": "Neue Aufnahmen werden standardmäßig zentral transkribiert, mit anonymer Sprechertrennung. Ist das Modell nicht bereit, werden Dateien zuerst archiviert. Legen Sie unten die Dauer pro Datei fest; es gibt kein Tageslimit.",
