  "本地 OCR 模型：": "Lokales OCR-Modell:",
  "OCR Worker 已就绪": "OCR-Worker ist bereit",
  "模型已安装，等待 OCR Worker 启动或安装 Native 运行时": "Modell installiert; warten, bis der OCR-Worker startet oder die native Laufzeit installiert wird",
  "下载并安装 OCR 模型": "OCR-Modell herunterladen und installieren",
  "新截图先归档，模型就绪后自动识别；升级前的旧截图不会自动回扫。模型下载不上传截图。": "Neue Screenshots werden zuerst archiviert und automatisch verarbeitet, sobald das Modell bereit ist. Vorhandene Screenshots werden nach einem Upgrade nicht nachträglich erfasst. Der Modell-Download lädt keine Screenshots hoch.",
  "高级 OCR 服务配置": "Erweiterte OCR-Diensteinstellungen",
  "默认由中央管理本地 Worker；改为远程地址会把已归档截图发送给该服务。": "Der zentrale Knoten verwaltet standardmäßig den lokalen Worker. Bei einer Remote-Adresse werden archivierte Screenshots an diesen Dienst gesendet.",
  "历史未安排": "Älteres Bild nicht eingeplant",
  "历史截图补识别": "OCR für ältere Screenshots nachholen",
  "升级前的截图不会自动识别。先预览数量，再手动安排；每次最多 100 张。": "Screenshots von vor dem Upgrade werden nicht automatisch verarbeitet. Sehen Sie sich die Anzahl in der Vorschau an und planen Sie sie dann manuell ein, jeweils bis zu 100.",
  "预览待补识别截图": "Vorschau der Screenshots mit ausstehender OCR-Nacherfassung",
  "本批 {0} 张{1}": "Dieser Stapel: {0} Screenshots{1}",
  "；还有更多可在本批完成后预览": "; weitere können nach Abschluss dieses Stapels in der Vorschau angezeigt werden",
  "确认安排本批 OCR": "OCR-Einplanung für diesen Stapel bestätigen",
  "Mote 页面受系统防截屏保护，已跳过；离开后自动恢复": "Mote-Seiten sind vor Screenshots geschützt und wurden übersprungen. Die Erfassung wird nach dem Verlassen automatisch fortgesetzt.",
  "屏幕采集：{0}": "Bildschirmerfassung: {0}",
  "与中央资料库共用登录，回答和历史对话自动保存。": "Nutzt dieselbe Anmeldung wie Ihr zentrales Archiv. Antworten und Gesprächsverlauf werden automatisch gespeichert.",
  "截图像素读取失败": "Screenshot-Pixel konnten nicht gelesen werden",
  "本地 OCR 服务正在准备，恢复后将自动继续。": "Die lokale OCR wird vorbereitet. Die Verarbeitung wird danach automatisch fortgesetzt.",
  "模型已安装，正在准备本地 OCR 服务；就绪后会自动处理": "Modell installiert. Die lokale OCR wird vorbereitet; die Verarbeitung startet automatisch, sobald sie bereit ist.",
  "目录建议默认": "Vom Katalog vorgeschlagener Standard",
  "当前模型不支持": "Von diesem Modell nicht unterstützt",
  "当前版本暂不支持": "Von dieser Version nicht unterstützt",
  "挡位来自所选模型的 Codex 目录。": "Die Denkstufen stammen aus dem Codex-Katalog des ausgewählten Modells.",
  "当前推理强度不受所选 Codex 模型支持，请重新选择。": "Das ausgewählte Codex-Modell unterstützt diese Denkstufe nicht. Wählen Sie eine andere Stufe.",
  "未取得 Codex 模型挡位，以下选项尚未核实。": "Die Denkstufen des Codex-Modells sind nicht verfügbar; diese Optionen sind ungeprüft.",
  "这里只展示已记录的输入和工具事件；未开启追踪或已过保留期的输入无法还原。": "Es werden nur aufgezeichnete Eingaben und Tool-Ereignisse angezeigt. Eingaben können nicht wiederhergestellt werden, wenn das Tracing deaktiviert war oder die Aufbewahrungsfrist abgelaufen ist.",
