  "记录已截断，不能还原完整输入。": "Diese Aufzeichnung wurde gekürzt; die vollständige Eingabe kann nicht wiederhergestellt werden.",
  "此页没有已保留的模型输入或工具事件。": "Auf dieser Seite gibt es keine aufbewahrten Modelleingaben oder Tool-Ereignisse.",
  "模型可见目录": "Für das Modell sichtbares Verzeichnis",
  "问一问当前可访问的虚拟目录，来自实际只读权限；这不代表某次回答已经读取这些内容。": "Das virtuelle Verzeichnis, auf das Ask aktuell mit seinen tatsächlichen Leseberechtigungen zugreifen kann. Verfügbarkeit bedeutet nicht, dass eine Antwort diesen Inhalt gelesen hat.",
  "可访问范围": "Zugänglicher Bereich",
  "正式资料": "Veröffentlichte Materialien",
  "实际输入与读取轨迹": "Aufgezeichnete Eingaben und Lesezugriffe",
  "设备范围": "Gerätebereich",
  "目录按页限量展示；没有列出不代表不存在。原始 Coding 事件包和磁盘路径不会作为模型目录公开。": "Verzeichnisse werden seitenweise begrenzt angezeigt; nicht aufgeführte Einträge sind nicht zwangsläufig nicht vorhanden. Rohe Coding-Ereignispakete und Festplattenpfade werden nicht als Modellverzeichnisse offengelegt.",
  "Coding Agent 上传": "Coding-Agent-Uploads",
  "接收成功表示原件已保留；正文发布、索引和记忆整理分别显示状态。": "Ein Empfang bestätigt, dass Originale aufbewahrt werden. Veröffentlichung, Indexierung und Erinnerungsverarbeitung haben separate Status.",
  "已接收事件": "Empfangene Ereignisse",
  "原件大小": "Originalgröße",
  "已发布资料": "Veröffentlichte Materialien",
  "暂无处理任务": "Noch keine Verarbeitungsaufgaben",
  "查看聚合正文": "Zusammengesetztes Transkript lesen",
  "暂无 Coding 来源，请在采集端启用 Coding Agent 同步。": "Noch keine Coding-Quellen. Aktivieren Sie die Coding-Agent-Synchronisierung in einem Erfassungsclient.",
  "功能插件": "Funktions-Plugins",
  "以下能力来自当前宿主的实际注册。关闭展示不删除资料，也不改变模型权限。": "Diese Funktionen stammen aus aktiven Host-Registrierungen. Das Deaktivieren einer Ansicht löscht keine Materialien und ändert keine Modellberechtigungen.",
