  "覆盖状态": "Abdeckung",
  "已记录的处理产物": "Aufgezeichnete Verarbeitungsergebnisse",
  "查看中央端发布的正文、版本、来源和处理产物。": "Veröffentlichte Inhalte, Versionen, Herkünfte und Verarbeitungsergebnisse durchsuchen.",
  "当前范围内暂无已发布资料。": "Keine veröffentlichten Materialien in diesem Bereich.",
  "保存记录（只读）": "Gespeicherte Aufzeichnung (schreibgeschützt)",
  "这是中央端返回的结构化记忆记录；下载文本是导出表示，实际模型输入请查看运行追踪。": "Dies ist die strukturierte Erinnerungsaufzeichnung, die der Server zurückgegeben hat. Der heruntergeladene Text ist ein Export; prüfen Sie die Ausführungs-Traces für die tatsächlichen Modelleingaben.",
  "专用视图暂不可用，请查看资料库或重试。": "Diese Ansicht ist nicht verfügbar. Durchsuchen Sie die Bibliothek oder versuchen Sie es erneut.",
  "已索引资料": "Indexierte Materialien",
  "项目未知（仅关联会话）": "Projekt unbekannt (nur Sitzung verknüpft)",
  "会话项目：{0}": "Sitzungsprojekt: {0}",
  "优先记住你的经历、感受和选择。代办任务线索放在“事件与资料”，需要时再查原文。": "Ihre Erlebnisse, Gefühle und Entscheidungen haben Vorrang. Hinweise zu delegierten Aufgaben bleiben unter „Ereignisse und Quellen“; öffnen Sie bei Bedarf die Originale.",
  "已关联项目（名称未知）": "Projekt verknüpft (Name unbekannt)",
  "这是历史版本，当前资料已更新。": "Dies ist eine ältere Version. Das aktuelle Material wurde aktualisiert.",
  "查看当前版本": "Aktuelle Version anzeigen",
  "来源已更正，正在重新整理资料。完成后可继续查看。": "Die Quelle wurde korrigiert und dieses Material wird neu aufbereitet. Sie können weiterlesen, sobald es fertig ist.",
  "已确认说话人：{0}": "Bestätigter Sprecher: {0}",
  "历史证据，仅用于核对当时的内容。": "Historischer Nachweis, aufbewahrt zur Überprüfung des damals Aufgezeichneten.",
  "返回阅读视图": "Zurück zur Leseansicht",
  "查看原始结构": "Rohstruktur anzeigen",
  "归档附件": "Archivierter Anhang",
  "匿名说话人：{0}": "Anonymer Sprecher: {0}",
  "接上一页": "Fortsetzung von der vorherigen Seite",
  "本片段未完，下一页继续。": "Dieser Abschnitt wird auf der nächsten Seite fortgesetzt.",
  "资料仍在整理，先展示当前可读的内容。": "Dieses Material wird noch verarbeitet. Der verfügbare Inhalt wird unten angezeigt.",
  "资料尚不完整，可在“来源与处理”中查看缺失情况。": "Dieses Material ist unvollständig. Unter „Herkunft und Verarbeitung“ sehen Sie, was fehlt.",
  "查看文件详情": "Dateidetails anzeigen",
  "记录时间：{0}": "Aufgezeichnet: {0}",
  "发生时间：{0}": "Aufgetreten: {0}",
  "待重新处理": "Erneute Verarbeitung erforderlich",
  "已生效": "Aktiv",
  "条记忆": "Erinnerungen",
  "查看记忆": "Erinnerungen anzeigen",
  "记忆通过自动审核和证据校验后直接生效，辅助问答。你可以随时查看来源、纠正或删除。": "Erinnerungen werden nach automatischer Prüfung und Nachweisvalidierung aktiv und helfen bei der Beantwortung von Fragen. Sie können jederzeit Quellen einsehen, sie korrigieren oder löschen.",
  "这是用户主动纠正的版本，原始说明已保留。": "Diese Version wurde vom Benutzer ausdrücklich korrigiert. Die ursprüngliche Aussage bleibt erhalten.",
  "已通过独立模型审核和引用校验。": "Hat die unabhängige Modellprüfung und Zitatsprüfung bestanden.",
  "模型未补充不确定性；可查看下方证据核对。": "Das Modell hat keine Angaben zur Unsicherheit ergänzt. Sie können die Nachweise unten prüfen.",
  "纠正记忆": "Erinnerung korrigieren",
  "删除这条记忆？原始资料保留；不会再用同一批旧证据生成这个结论，有新证据时可重新判断。": "Diese Erinnerung löschen? Das Originalmaterial bleibt erhalten. Dieselben alten Nachweise erzeugen diese Schlussfolgerung nicht erneut; neue Nachweise können eine Neubewertung auslösen.",
  "填写纠正后的内容，保存后直接生效。你的说明会作为原始证据保存；旧记忆及其证据仍可查看，适用项目保持不变。": "Geben Sie den korrigierten Inhalt ein. Er wird beim Speichern aktiv. Ihre Angabe wird als ursprünglicher Nachweis gespeichert; frühere Erinnerungen und ihre Nachweise bleiben verfügbar, der Projektbezug bleibt unverändert.",
  "纠正后的内容": "Korrigierter Inhalt",
  "这条旧版记忆尚未通过当前的自动生效校验。重新提取当前范围可重新处理，无需逐条确认。": "Diese Alt-Erinnerung hat die aktuellen Aktivierungsprüfungen nicht bestanden. Extrahieren Sie Erinnerungen für den aktuellen Bereich, um sie erneut zu verarbeiten; eine einzelne Bestätigung ist nicht erforderlich.",
  "记忆以文本保存，可按需查看概览、内容与边界、原始证据。通过自动审核和证据校验后直接生效，你可以随时纠正或删除。历史资料提取按窗口处理已圈定的积压，每轮窗口上限控制成本。": "Erinnerungen werden als Text gespeichert. Sehen Sie sich bei Bedarf Übersichten, Inhalte, Grenzen und ursprüngliche Nachweise an. Sie werden nach automatischer Prüfung und Nachweisvalidierung wirksam, und Sie können sie jederzeit korrigieren oder löschen. Die historische Extraktion verarbeitet einen festen Rückstand in Fenstern; das Fensterlimit pro Runde kontrolliert die Kosten.",
  "4 提取记忆": "4 Erinnerungen extrahieren",
  "确认后保存记录，并在后台分批提取记忆；记忆通过自动审核和证据校验后直接生效。": "Nach der Bestätigung werden Aufzeichnungen gespeichert und Erinnerungen in Hintergrund-Stapeln extrahiert. Erinnerungen werden nach automatischer Prüfung und Nachweisvalidierung aktiv.",
  "尚未生效": "Noch nicht aktiv",
  "未补充判断边界；可查看下方原始说明。": "Es wurden keine Grenzen angegeben. Sie können die ursprüngliche Aussage unten einsehen.",
  "这是你的主动纠正；原始说明和旧版本均已保留。": "Dies ist Ihre ausdrückliche Korrektur. Die ursprüngliche Aussage und frühere Versionen bleiben erhalten.",
  "已过期": "Abgelaufen",
  "本次提取方案": "Rezepte für diese Extraktion",
  "已选 {0} 项": "{0} ausgewählt",
  "默认提取方式": "Standardextraktion",
  "选择仅用于本次提取。各方案会等待自己需要的资料，已完成的结果可立即查看；不选择时使用默认提取方式。": "Diese Auswahl gilt nur für diese Extraktion. Jedes Rezept wartet auf das von ihm benötigte Material, und fertige Ergebnisse sind sofort verfügbar. Lassen Sie alles unausgewählt, um die Standardextraktion zu verwenden.",
  "选择本次记忆方案": "Rezepte für diese Extraktion auswählen",
  "恢复默认提取方式": "Standardextraktion verwenden",
  "每次最多选择 8 项方案。": "Wählen Sie bis zu 8 Rezepte pro Extraktion.",
  "等待资料处理": "Warten auf Materialverarbeitung",
  "提取文字（OCR / 转写）": "Extrahierter Text (OCR / Transkription)",
  "完整资料": "Vollständiges Material",
  "附件文字": "Anhangtext",
