  "已就绪的方案已继续处理。其余方案等待所需资料，已保存的记忆可以立即查看。": "Bereite Rezepte wurden fortgesetzt. Andere Rezepte warten auf ihr benötigtes Material; gespeicherte Erinnerungen sind jetzt verfügbar.",
  "各方案进度": "Fortschritt pro Rezept",
  "已完成 {0} 批": "{0} Stapel abgeschlossen",
  "所需资料：{0}": "Benötigtes Material: {0}",
  "查看来源与处理": "Quelle und Verarbeitung anzeigen",
  "暂停等待与后续批次": "Wartende Eingaben und verbleibende Stapel pausieren",
  "取消未完成方案": "Unfertige Rezepte abbrechen",
  "重新检查未完成方案": "Unfertige Rezepte erneut prüfen",
  "重试会复用仍有效的提取结果；结果不可用或资料、设置变化时，可能重新提取。历史用量会保留。": "Wiederholungen nutzen weiterhin gültige Extraktionsergebnisse erneut. Sind Ergebnisse nicht verfügbar oder haben sich Materialien oder Einstellungen geändert, kann die Extraktion erneut laufen. Der bisherige Verbrauch bleibt erhalten.",
  "所需资料仍在处理中，就绪后会自动继续。": "Das benötigte Material wird noch verarbeitet. Dieses Rezept wird automatisch fortgesetzt, sobald es bereit ist.",
  "所需资料处理失败，请查看来源并修复后重新检查。": "Die Verarbeitung des benötigten Materials ist fehlgeschlagen. Prüfen Sie die Quelle, beheben Sie die Verarbeitung und prüfen Sie erneut.",
  "所需资料不可用，请查看来源与处理状态。": "Das benötigte Material ist nicht verfügbar. Prüfen Sie Quelle und Verarbeitungsstatus.",
  "新产物不在本次选择的证据范围内，请重新发起提取。": "Das neue Ergebnis liegt außerhalb der für diese Anfrage ausgewählten Nachweise. Starten Sie eine neue Extraktion.",
  "本次选择的方案已不可用，请重新选择方案并发起提取。": "Ein ausgewähltes Rezept ist nicht mehr verfügbar. Wählen Sie Rezepte und starten Sie eine neue Extraktion.",
  "来源授权已撤销，未完成的方案已停止。": "Die Quellenautorisierung wurde widerrufen. Unfertige Rezepte wurden gestoppt.",
  " · {0} 项已停止": " · {0} gestoppt",
  "整体处理：": "Gesamtverarbeitung: ",
  "未启用": "Nicht aktiviert",
  "原始转写已保留，尚未校正；说话人分离与对话整理的结果另行生成。": "Das ursprüngliche Transkript bleibt erhalten und ist unkorrigiert. Sprechertrennung und Dialogaufbereitung erzeugen separate Ergebnisse.",
  "展开原始转写（未校正）": "Originaltranskript anzeigen (unkorrigiert)",
  "说话人分离未完成，已保留原始转写。": "Die Sprechertrennung wurde nicht abgeschlossen. Das ursprüngliche Transkript bleibt erhalten.",
  "资料记忆提取已停止自动重试：失败 {0}/{1} 次。检查配置后可手动重试。": "Automatische Wiederholungen der Material-Erinnerungsextraktion wurden nach {0}/{1} Fehlern gestoppt. Prüfen Sie die Konfiguration und versuchen Sie es dann manuell erneut.",
  "校正此段文字": "Diesen Abschnitt korrigieren",
  "仅保存人工校正，不调用模型；原件和原始转写保留。": "Speichert eine manuelle Korrektur ohne Modellaufruf. Originaldatei und -transkript bleiben erhalten.",
  "保存校正": "Korrektur speichern",
  "纠正此段": "Diesen Abschnitt korrigieren",
  "仅从这条资料提取记忆": "Erinnerungen nur aus dieser Aufzeichnung extrahieren",
  "仅从这份正式资料提取记忆": "Erinnerungen nur aus diesem veröffentlichten Material extrahieren",
  "这份正式资料暂不能单独提取记忆，请查看来源与处理状态。": "Dieses veröffentlichte Material ist für eine einzelne Erinnerungsextraktion noch nicht bereit. Prüfen Sie Quelle und Verarbeitungsstatus.",
  "查看正式资料并提取记忆": "Veröffentlichtes Material öffnen, um Erinnerungen zu extrahieren",
  "此来源的原始记录需通过正式资料提取记忆。": "Erinnerungen aus dieser Quelle werden über das veröffentlichte Material extrahiert.",
  "查看正式资料": "Veröffentlichte Materialien anzeigen",
  "提取所选资料的记忆": "Erinnerungen aus der ausgewählten Aufzeichnung extrahieren",
  "仅这份正式资料": "Nur dieses veröffentlichte Material",
  "当前正式资料 · {0} 个证据片段": "Aktuelles veröffentlichtes Material · {0} Nachweissegmente",
  "所选正式资料已变化或暂不可提取，请重新打开当前版本。": "Das ausgewählte veröffentlichte Material hat sich geändert oder ist nicht bereit. Öffnen Sie die aktuelle Version erneut.",
  "仅这条资料": "Nur diese Aufzeichnung",
  "本次提取只使用下方资料，不使用顶部的时间范围。": "Diese Extraktion verwendet nur die untenstehende Aufzeichnung, unabhängig vom Zeitbereich oben.",
  "所选资料无效，请重新打开原始记录。": "Die ausgewählte Aufzeichnung ist ungültig. Öffnen Sie die ursprüngliche Aufzeichnung erneut.",
  "清除资料选择，恢复时间范围": "Auswahl der Aufzeichnung aufheben und Zeitbereich verwenden",
  "问答读取原图尚未开启。请在中央感知设置中允许查询模型按需读取原图，再重新提问。": "Der Zugriff auf Originalbilder für Abfragen ist deaktiviert. Aktivieren Sie den bedarfsgesteuerten Bildzugriff für das Abfragemodell in den Einstellungen der zentralen Wahrnehmung und stellen Sie die Frage erneut.",
  "OCR 已取消": "OCR abgebrochen",
  "中央文字识别已取消，截图已保留；当前没有正在处理的识别任务。": "Die zentrale OCR wurde abgebrochen. Der Screenshot bleibt erhalten; derzeit läuft keine Erkennungsaufgabe.",
  "OCR 未启用": "OCR nicht aktiviert",
  "中央文字识别未启用，截图已保留；当前不会自动识别文字。": "Die zentrale OCR ist nicht aktiviert. Der Screenshot bleibt erhalten; Text wird nicht automatisch erkannt.",
  "OCR 暂不可用": "OCR nicht verfügbar",
  "中央文字识别模型尚未安装，截图已保留。": "Das zentrale OCR-Modell ist nicht installiert. Der Screenshot bleibt erhalten.",
  "中央文字识别被阻止，请检查中央感知配置与处理状态。截图已保留。": "Die zentrale OCR ist blockiert. Prüfen Sie die Konfiguration der zentralen Wahrnehmung und den Verarbeitungsstatus. Der Screenshot bleibt erhalten.",
  "截图已保存，文字识别任务正在排队或处理。": "Screenshot gespeichert. Die Texterkennung ist in der Warteschlange oder wird verarbeitet.",
  "文字识别已完成，下方显示这条记录保留的全文。": "Die Texterkennung ist abgeschlossen. Der vollständige aufbewahrte Text wird unten angezeigt.",
  "文字识别失败，截图已保留。": "Die Texterkennung ist fehlgeschlagen. Der Screenshot bleibt erhalten.",
  "日期按当前浏览器时区显示。这里展示已同步到中央节点的记录；可刷新查看文字识别的最新状态与结果。": "Datumsangaben verwenden die aktuelle Browser-Zeitzone. Diese Aufzeichnungen wurden mit dem zentralen Knoten synchronisiert; aktualisieren Sie, um den neuesten Status und die Ergebnisse der Texterkennung zu sehen.",
  "当前处理尚未结束，请稍后再试。": "Der aktuelle Verarbeitungsaufruf ist noch nicht abgeschlossen. Bitte versuchen Sie es später erneut.",
  "上次处理是否结束未知，重试可能重复执行。请确认后继续。": "Es ist unbekannt, ob der vorherige Verarbeitungsaufruf abgeschlossen wurde. Ein erneuter Versuch könnte ihn doppelt ausführen. Bestätigen Sie, um fortzufahren.",
  "当前调用尚在等待结束；此时不能重试。": "Der aktuelle Aufruf wird noch abgewartet. Ein erneuter Versuch ist derzeit nicht möglich.",
  "本次处理已取消，不再保存后续结果；原件和已保存的成果保留。": "Dieser Verarbeitungslauf wurde abgebrochen. Weitere Ergebnisse werden nicht gespeichert; Originale und bereits gespeicherte Ergebnisse bleiben erhalten.",
  "取消本次处理": "Diesen Verarbeitungslauf abbrechen",
  "确认重试": "Wiederholung bestätigen",
