  "Agent 目录": "Agent-Verzeichnis",
  "这是只读虚拟目录，目录条目按需披露。": "Dies ist ein schreibgeschütztes virtuelles Verzeichnis. Einträge werden bei Bedarf offengelegt.",
  "从目录开始，逐层展开 Agent 可以读取的内容。": "Beginnen Sie mit dem Verzeichnis und erweitern Sie Ebene für Ebene, was der Agent lesen kann.",
