  "想问的问题": "Ihre Frage",
  "输入问题，看看启动时会带上哪些记忆线索": "Geben Sie eine Frage ein, um die anfänglichen Erinnerungshinweise in der Vorschau zu sehen",
  "预览首次上下文": "Anfangskontext in der Vorschau anzeigen",
  "默认包含：系统规则、只读工具说明、当前问题、时间与设备范围，以及最多 5 条记忆线索。": "Standardmäßig enthalten: Systemregeln, Beschreibungen der schreibgeschützten Tools, die Frage, Zeit- und Gerätebereich sowie bis zu 5 Erinnerungshinweise.",
  "已有对话会按预算带入历史或工作摘要；此处预览的是没有历史的新对话。": "Bestehende Gespräche enthalten je nach Budget Verlauf oder Arbeitszusammenfassungen. Diese Vorschau ist ein neues Gespräch ohne Verlauf.",
  "完整目录、文件正文和原图需要按需读取，原图还受独立授权控制。": "Vollständige Verzeichnisse, Dateiinhalte und Originalbilder werden bei Bedarf gelesen. Bilder erfordern eine separate Autorisierung.",
