  "请先在中央节点完成飞书账号授权，再连接录音。": "Autorisieren Sie Feishu auf dem zentralen Knoten, bevor Sie Aufnahmen verbinden.",
  "中央节点需要安装 DWS CLI 并完成钉钉账号授权。": "Installieren Sie DWS CLI und autorisieren Sie DingTalk auf dem zentralen Knoten.",
  "请先在中央节点完成钉钉账号授权，再连接录音。": "Autorisieren Sie DingTalk auf dem zentralen Knoten, bevor Sie Aufnahmen verbinden.",
  "账号已变化，请重新连接并确认同步范围。": "Das Konto hat sich geändert. Verbinden Sie es erneut und bestätigen Sie den Synchronisierungsbereich.",
  "读取权限不足或授权已失效，请重新连接后重试。": "Leseberechtigungen fehlen oder die Autorisierung ist abgelaufen. Verbinden Sie erneut und versuchen Sie es noch einmal.",
  "厂商转写尚未就绪，将自动重试。": "Das Anbieter-Transkript ist noch nicht bereit. Mote versucht es automatisch erneut.",
  "同步未完成，请检查节点网络与厂商读取权限后重试。": "Die Synchronisierung wurde nicht abgeschlossen. Prüfen Sie die Knotenverbindung und die Leseberechtigungen des Anbieters und versuchen Sie es erneut.",
  "连接中央节点已经授权的厂商账号，然后选择首次导入时间。": "Verbinden Sie das auf dem zentralen Knoten autorisierte Anbieterkonto und wählen Sie dann den Bereich des ersten Imports.",
  "连接已授权账号": "Autorisiertes Konto verbinden",
  "首次授权帮助": "Hilfe zur ersten Autorisierung",
  "在中央节点安装并登录官方 Lark CLI。需要妙记搜索、基础信息、产物读取和媒体导出权限。": "Installieren Sie die offizielle Lark CLI auf dem zentralen Knoten und melden Sie sich an. Berechtigungen für Minutes-Suche, Metadaten, Artefakte und Medienexport sind erforderlich.",
  "在中央节点安装并登录官方 DWS CLI；所在组织需开启 CLI 接入。钉钉适配器尚未完成真实账号验证。": "Installieren Sie die offizielle DWS CLI auf dem zentralen Knoten und melden Sie sich an. Ihre Organisation muss den CLI-Zugriff aktivieren. Der DingTalk-Adapter wurde noch nicht mit einem echten Konto verifiziert.",
  "首次历史导入起点": "Startpunkt des ersten Verlaufsimports",
  "导入终点（留空持续同步）": "Importende (leer lassen für laufende Synchronisierung)",
  "启用录音同步": "Aufnahmesynchronisierung aktivieren",
  "保存并开始同步": "Speichern und Synchronisierung starten",
  "重试失败步骤": "Fehlgeschlagene Schritte erneut versuchen",
  "已归档转写 {0} 条，音频 {1} 条；等待 {2} 步，需处理 {3} 步。": "{0} Transkripte und {1} Audiodateien archiviert; {2} Schritte ausstehend, {3} erfordern Bearbeitung.",
  "同步步骤与状态": "Synchronisierungsschritte und Status",
  "尝试 {0} 次": "{0} Versuche",
  "录音归档": "Aufnahmearchiv",
  "照常使用录音笔。厂商完成上传和转写后，Mote 自动归档并生成可追溯的 Memory。": "Verwenden Sie Ihr Aufnahmegerät wie gewohnt. Nachdem der Anbieter eine Aufnahme hochgeladen und transkribiert hat, archiviert Mote sie und erstellt nachverfolgbare Erinnerungen.",
  "默认用转写生成洞察，原始音频在后台备份。厂商端删除后，Mote 归档继续保留。停止同步或断开连接会保留历史资料。": "Transkripte werden standardmäßig für Erkenntnisse verwendet; das Originalaudio wird im Hintergrund gesichert. Mote behält seine Archive, nachdem der Anbieter sie löscht, die Synchronisierung gestoppt oder das Konto getrennt wird.",
  "原始录音": "Originalaufnahme",
  "回听原始录音": "Originalaufnahme abspielen",
  "最近归档的录音": "Zuletzt archivierte Aufnahmen",
  "中央导出与问答、资料库共用登录状态。": "Zentrale Exporte, Chat und Archiv teilen sich eine Anmeldung.",
  "中央登录与账户": "Zentrale Anmeldung und Konto",
  "登录会话已变更，请重新打开中央页面。": "Ihre Anmeldesitzung hat sich geändert. Öffnen Sie die zentrale Seite erneut.",
  "请在中央「行动」设置中授权此设备，或登录中央管理会话。": "Autorisieren Sie dieses Gerät in den zentralen „Aktionen“-Einstellungen oder melden Sie sich als zentraler Eigentümer an.",
  "先在连接设置选择中央节点，再登录中央管理页面。": "Wählen Sie zuerst einen zentralen Knoten in den Verbindungseinstellungen und melden Sie sich dann an.",
