  "查看中央手动升级说明": "Hinweis zum manuellen Upgrade des zentralen Knotens lesen",
  "查看转写归档与音频备份状态": "Transkriptarchive und Audio-Sicherungsstatus prüfen",
  "查看资料上下文中的澄清请求。": "Klärungsanfragen im Kontext des Materials anzeigen.",
  "查看总量和失败": "Summen/Fehlschläge beobachten",
  "查看最后联系和采集时间": "Letzten Kontakt/letzte Erfassung anzeigen",
