  "尚未接入，查看首次授权和同步设置": "Nicht verbunden. Erstautorisierung und Synchronisierungseinrichtung prüfen.",
  "尚未启用 MCP。请在设置 → 模型与服务 → 来源与外部应用中开启 MCP，并配置独立读令牌后重启；写入还需明确启用并设置允许的信源。": "MCP ist nicht aktiviert. Aktivieren Sie in Einstellungen → Modelle und Dienste → Quellen und externe Apps MCP und konfigurieren Sie ein eigenständiges Lesetoken, dann neu starten. Schreiben erfordert außerdem eine explizite Aktivierung und erlaubte Quellen.",
