  "原任务入口当前不可用，请从主导航继续。": "Der ursprüngliche Aufgabeneinstieg ist derzeit nicht verfügbar. Fahren Sie über die Hauptnavigation fort.",
  "这里仅核对首个关联执行记录；还有 {0} 个关联记录，可在技术详情继续查看。已有补充问题单独显示在下方。": "Hier wird nur der erste verknüpfte Ausführungsdatensatz geprüft. Es gibt {0} weitere verknüpfte Datensätze, die in den technischen Details eingesehen werden können. Vorhandene Anschlussfragen werden unten separat angezeigt.",
  "此资料库分类当前不可用。请从资料库分类中选择可用入口。": "Diese Bibliothekskategorie ist derzeit nicht verfügbar. Wählen Sie einen verfügbaren Einstieg aus den Bibliothekskategorien.",
  "厂商转写格式尚不支持。音频备份是独立步骤，请分别核对转写与音频的状态。": "Das Transkriptformat des Anbieters wird nicht unterstützt. Die Audiosicherung ist ein separater Schritt; prüfen Sie Transkript- und Audiostatus einzeln.",
  "同步未完成（原因代码：{0}）。请查看同步步骤，核对实际原因后再重试。": "Synchronisierung nicht abgeschlossen (Ursachencode: {0}). Prüfen Sie die Synchronisierungsschritte und die tatsächliche Ursache, bevor Sie es erneut versuchen.",
  "核对原因后，可使用上方「重试失败步骤」。转写与音频状态分别核对。": "Nach Prüfung der Ursache können Sie oben „Fehlgeschlagene Schritte erneut versuchen“ verwenden. Prüfen Sie Transkript- und Audiostatus getrennt.",
