  "仅在已知范围时填写；与准确人数互斥": "Nur bei bekanntem Bereich ausfüllen; kann nicht mit einer genauen Anzahl kombiniert werden",
  "本地说话人分离 · WeSpeaker 中文": "Lokale Sprechertrennung · WeSpeaker Chinesisch",
