  "未得到范围内的候选；已保留自动结果及候选，不会补造或隐藏说话人。": "Kein Kandidat erfüllte den deklarierten Bereich. Automatische Ergebnisse und Kandidaten bleiben erhalten; Sprecher werden weder erfunden noch ausgeblendet.",
  "归档不代表整理完成。": "Archivierung bedeutet nicht, dass die Verarbeitung abgeschlossen ist.",
