  "采集与随手记的上传批次；其他上传结果可在采集与存储详情查看。": "Upload-Batches für Erfassungen und Kurznotizen. Andere Upload-Ergebnisse bleiben in den Erfassungs- und Speicherdetails verfügbar.",
