  "正在核验能力…": "Fähigkeiten werden überprüft…",
  "能力已核验。启用与记忆方案仍需单独选择。": "Fähigkeiten überprüft. Aktivierung und Auswahl eines Erinnerungsplans bleiben separate Entscheidungen.",
