  "核验使用生成测试资料，可能产生模型与 Embedding 费用；Hindsight 会启动 Docker 服务与模型。不会读取或回填个人历史。": "Die Überprüfung verwendet generierte Testdaten und kann Modell- und Embedding-Gebühren verursachen. Hindsight startet seinen Docker-Dienst und seine Modelle. Es liest keinen persönlichen Verlauf und füllt ihn nicht nach.",
