  "查看已安装插件": "Installierte Plugins anzeigen",
  "离开此引导不会撤销已登记的安装或核验。": "Das Verlassen dieser Anleitung macht eine bereits registrierte Installation oder Überprüfung nicht rückgängig.",
  "填写连接配置。保存不会运行核验、启用插件或更换记忆方案。": "Verbindungseinstellungen eingeben. Das Speichern führt keine Überprüfung aus, aktiviert das Plugin nicht und ändert den Erinnerungsplan nicht.",
