  "结构化内容未采集：Chrome 窗口、站点授权或遮挡校验未通过；应用时长按所选设置记录": "Strukturierte Inhalte nicht erfasst: Chrome-Fenster-, Website-Berechtigungs- oder Sichtbarkeitsprüfungen fehlgeschlagen; die App-Dauer folgt Ihrer Auswahl",
  "切换语言会重新加载页面，请先保存未提交的修改。继续？": "Beim Wechseln der Sprache wird die Seite neu geladen. Speichern Sie zuerst ausstehende Änderungen. Fortfahren?",
